window.KHO_DATA_L3_TIENGANH = [
{"lop":3,"mon":"Tiếng Anh","tuan":1,"tiet":1,"bai":"Starter — Làm quen SGK & hướng dẫn học Tiếng Anh 3","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- làm quen SGK Tiếng Anh 3 (Global Success), ôn bảng chữ cái (Alphabet) và số đếm (Numbers); tạo hứng thú, nội quy lớp học tiếng Anh.\n2. Năng lực chung: Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất: Chăm chỉ, tự tin, trung thực trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 1.2 CB1a: Phát hiện được độ tin cậy và độ chính xác của các nguồn chung của dữ liệu, thông tin và nội dung số: HS phân biệt được giọng người bản ngữ với giọng do máy tạo ra khi nghe cùng một câu chào.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh, giới thiệu SGK Tiếng Anh (Global Success), cách học và đồ dùng.\n- Tạo không khí vui vẻ, khơi gợi hứng thú học tiếng Anh.","hs":"- HS làm quen SGK, đồ dùng; chia sẻ điều đã biết/muốn học."},{"ten":"2. Nội dung chính","gv":"- GV tổ chức làm quen SGK Tiếng Anh 3 (Global Success), ôn bảng chữ cái (Alphabet) và số đếm (Numbers); tạo hứng thú, nội quy lớp học tiếng Anh.","hs":"- HS thực hiện nhiệm vụ theo hướng dẫn."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập/làm bài, chữa và nhận xét.","hs":"- HS làm bài, tự đánh giá, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV giới thiệu bộ học liệu số đi kèm SGK Tiếng Anh 3 (Global Success): tệp audio của từng Unit, mã QR in trong sách, kí hiệu tai nghe báo chỗ có bài nghe; GV mở thử tệp audio bảng chữ cái và số đếm cho HS nghe giọng người bản ngữ, chỉ rõ trang nào trong sách ứng với tệp vừa mở.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV mở cho cả lớp nghe cùng một câu chào “Hello. How are you?” hai lần: một lần do người bản ngữ đọc trong audio SGK, một lần do công cụ đọc tự động của máy đọc; HS đoán giọng nào là người, giọng nào là máy và chỉ ra chỗ máy đọc đều đều, thiếu ngữ điệu. GV thao tác toàn bộ, HS chỉ nghe và trả lời.\n⚠ (Miền 4: An toàn) Trong giờ tiếng Anh, máy tính, loa và điện thoại là của GV: HS không tự cầm, không tự bật, không tự tắt. Loa mở vừa đủ nghe; nếu nghe bằng tai nghe thì để âm lượng nhỏ, nghe khoảng 10-15 phút thì nghỉ. HS không nói và không gõ tên đầy đủ, tên trường lớp, số điện thoại vào bất kì trang web nào GV mở trên màn hình.","hs":"- HS chỉ ra được trong SGK chỗ nào có bài nghe và biết bài nghe được mở từ tệp audio hoặc mã QR.\n- HS phân biệt được giọng người bản ngữ với giọng do máy tạo ra khi nghe cùng một câu chào."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":1,"tiet":2,"bai":"Unit 1 — Hello — Lesson 1 (Greetings & introductions) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết hello, hi, bye, goodbye; nghe hiểu mẫu câu \"Hello. Hi. / Goodbye. Bye.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Hello. Hi. / Goodbye. Bye.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: hello, hi, bye, goodbye; mẫu câu: Hello. Hi. / Goodbye. Bye.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc hello, hi, bye, goodbye, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 1 “Hello” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Greetings & introductions”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 1 “Hello”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: hello, hi, bye, goodbye.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Hello. Hi. / Goodbye. Bye.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Hello. Hi. / Goodbye. Bye.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 1 “Hello” cho HS nghe người bản ngữ đọc hello, hi, bye, goodbye; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt hello, hi, bye, goodbye và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc hello, hi, bye, goodbye, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 1 “Hello”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":1,"tiet":3,"bai":"Unit 1 — Hello — Lesson 1 (Greetings & introductions) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết hello, hi, bye, goodbye; nghe hiểu mẫu câu \"Hello. Hi. / Goodbye. Bye.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Hello. Hi. / Goodbye. Bye.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: hello, hi, bye, goodbye; mẫu câu: Hello. Hi. / Goodbye. Bye.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Greetings & introductions” (Unit 1 “Hello”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 1 “Hello”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Hello. Hi. / Goodbye. Bye.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":1,"tiet":4,"bai":"Unit 1 — Hello — Lesson 2 (Asking how someone is) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết fine, thank you, how, you; nghe hiểu mẫu câu \"How are you? – I'm fine, thank you.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How are you? – I'm fine, thank you.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: fine, thank you, how, you; mẫu câu: How are you? – I'm fine, thank you.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “How are you? – I'm fine, thank you”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 1 “Hello” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Asking how someone is”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 1 “Hello”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: fine, thank you, how, you.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"How are you? – I'm fine, thank you.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"How are you? – I'm fine, thank you.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 1 “Hello” — Lesson 2 (Asking how someone is) cho HS nghe mẫu câu “How are you? – I'm fine, thank you” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ fine, thank you, how, you vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “How are you? – I'm fine, thank you”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong fine, thank you, how, you mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":2,"tiet":1,"bai":"Unit 1 — Hello — Lesson 2 (Asking how someone is) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết fine, thank you, how, you; nghe hiểu mẫu câu \"How are you? – I'm fine, thank you.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How are you? – I'm fine, thank you.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: fine, thank you, how, you; mẫu câu: How are you? – I'm fine, thank you.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Asking how someone is” (Unit 1 “Hello”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 1 “Hello”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"How are you? – I'm fine, thank you.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":2,"tiet":2,"bai":"Unit 1 — Hello — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Hello\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 1; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 1 “Hello” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 1 “Hello”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 1 “Hello” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Hello.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 1 “Hello”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":2,"tiet":3,"bai":"Unit 1 — Hello — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Hello\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 1; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 1 “Hello” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 1 “Hello”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 1 “Hello”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 1 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 1 “Hello” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Hello (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 1 “Hello” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Hello khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":2,"tiet":4,"bai":"Unit 2 — Our names — Lesson 1 (Asking & telling names) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết name, what, spell; nghe hiểu mẫu câu \"What's your name? – My name's Nam.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's your name? – My name's Nam.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: name, what, spell; mẫu câu: What's your name? – My name's Nam.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc name, what, spell, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 2 “Our names” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Asking & telling names”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 2 “Our names”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: name, what, spell.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What's your name? – My name's Nam.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What's your name? – My name's Nam.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 2 “Our names” cho HS nghe người bản ngữ đọc name, what, spell; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt name, what, spell và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc name, what, spell, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 2 “Our names”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":3,"tiet":1,"bai":"Unit 2 — Our names — Lesson 1 (Asking & telling names) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết name, what, spell; nghe hiểu mẫu câu \"What's your name? – My name's Nam.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's your name? – My name's Nam.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: name, what, spell; mẫu câu: What's your name? – My name's Nam.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Asking & telling names” (Unit 2 “Our names”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 2 “Our names”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What's your name? – My name's Nam.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":3,"tiet":2,"bai":"Unit 2 — Our names — Lesson 2 (Spelling names) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết letters A–Z, spell; nghe hiểu mẫu câu \"How do you spell your name? – N-A-M.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How do you spell your name? – N-A-M.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: letters A–Z, spell; mẫu câu: How do you spell your name? – N-A-M.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “How do you spell your name? – N-A-M”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 2 “Our names” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Spelling names”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 2 “Our names”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: letters A–Z, spell.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"How do you spell your name? – N-A-M.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"How do you spell your name? – N-A-M.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 2 “Our names” — Lesson 2 (Spelling names) cho HS nghe mẫu câu “How do you spell your name? – N-A-M” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ letters A–Z, spell vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “How do you spell your name? – N-A-M”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong letters A–Z, spell mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":3,"tiet":3,"bai":"Unit 2 — Our names — Lesson 2 (Spelling names) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết letters A–Z, spell; nghe hiểu mẫu câu \"How do you spell your name? – N-A-M.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How do you spell your name? – N-A-M.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: letters A–Z, spell; mẫu câu: How do you spell your name? – N-A-M.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Spelling names” (Unit 2 “Our names”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 2 “Our names”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"How do you spell your name? – N-A-M.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":3,"tiet":4,"bai":"Unit 2 — Our names — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our names\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 2; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 2 “Our names” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 2 “Our names”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 2 “Our names” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Our names.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 2 “Our names”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":4,"tiet":1,"bai":"Unit 2 — Our names — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our names\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 2; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 2 “Our names” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 2 “Our names”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 2 “Our names”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 2 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 2 “Our names” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Our names (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 2 “Our names” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Our names khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":4,"tiet":2,"bai":"Unit 3 — Our friends — Lesson 1 (Introducing a friend) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết friend, this, he, she; nghe hiểu mẫu câu \"This is Mai. – Hello, Mai.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is Mai. – Hello, Mai.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: friend, this, he, she; mẫu câu: This is Mai. – Hello, Mai.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc friend, this, he, she, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 3 “Our friends” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Introducing a friend”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 3 “Our friends”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: friend, this, he, she.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"This is Mai. – Hello, Mai.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"This is Mai. – Hello, Mai.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 3 “Our friends” cho HS nghe người bản ngữ đọc friend, this, he, she; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt friend, this, he, she và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc friend, this, he, she, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 3 “Our friends”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":4,"tiet":3,"bai":"Unit 3 — Our friends — Lesson 1 (Introducing a friend) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết friend, this, he, she; nghe hiểu mẫu câu \"This is Mai. – Hello, Mai.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is Mai. – Hello, Mai.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: friend, this, he, she; mẫu câu: This is Mai. – Hello, Mai.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Introducing a friend” (Unit 3 “Our friends”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 3 “Our friends”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"This is Mai. – Hello, Mai.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":4,"tiet":4,"bai":"Unit 3 — Our friends — Lesson 2 (Talking about friends) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết he, she, is, my friend; nghe hiểu mẫu câu \"Who's that? – He's/She's my friend.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Who's that? – He's/She's my friend.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: he, she, is, my friend; mẫu câu: Who's that? – He's/She's my friend.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Who's that? – He's/She's my friend”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 3 “Our friends” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Talking about friends”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 3 “Our friends”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: he, she, is, my friend.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Who's that? – He's/She's my friend.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Who's that? – He's/She's my friend.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 3 “Our friends” — Lesson 2 (Talking about friends) cho HS nghe mẫu câu “Who's that? – He's/She's my friend” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ he, she, is, my friend vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Who's that? – He's/She's my friend”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong he, she, is, my friend mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":5,"tiet":1,"bai":"Unit 3 — Our friends — Lesson 2 (Talking about friends) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết he, she, is, my friend; nghe hiểu mẫu câu \"Who's that? – He's/She's my friend.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Who's that? – He's/She's my friend.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: he, she, is, my friend; mẫu câu: Who's that? – He's/She's my friend.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Talking about friends” (Unit 3 “Our friends”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 3 “Our friends”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Who's that? – He's/She's my friend.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":5,"tiet":2,"bai":"Unit 3 — Our friends — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our friends\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 3; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 3 “Our friends” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 3 “Our friends”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 3 “Our friends” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Our friends.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 3 “Our friends”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":5,"tiet":3,"bai":"Unit 3 — Our friends — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our friends\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 3; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 3 “Our friends” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 3 “Our friends”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 3 “Our friends”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 3 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 3 “Our friends” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Our friends (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 3 “Our friends” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Our friends khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":5,"tiet":4,"bai":"Unit 4 — Our bodies — Lesson 1 (Parts of the body) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết arm, leg, head, hand; nghe hiểu mẫu câu \"This is my arm. These are my legs.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my arm. These are my legs.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: arm, leg, head, hand; mẫu câu: This is my arm. These are my legs.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc arm, leg, head, hand, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 4 “Our bodies” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Parts of the body”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 4 “Our bodies”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: arm, leg, head, hand.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"This is my arm. These are my legs.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"This is my arm. These are my legs.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 4 “Our bodies” cho HS nghe người bản ngữ đọc arm, leg, head, hand; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt arm, leg, head, hand và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc arm, leg, head, hand, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 4 “Our bodies”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":6,"tiet":1,"bai":"Unit 4 — Our bodies — Lesson 1 (Parts of the body) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết arm, leg, head, hand; nghe hiểu mẫu câu \"This is my arm. These are my legs.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my arm. These are my legs.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: arm, leg, head, hand; mẫu câu: This is my arm. These are my legs.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Parts of the body” (Unit 4 “Our bodies”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 4 “Our bodies”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"This is my arm. These are my legs.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":6,"tiet":2,"bai":"Unit 4 — Our bodies — Lesson 2 (Describing bodies) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết big, small, long, short; nghe hiểu mẫu câu \"My arms are long. My legs are short.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"My arms are long. My legs are short.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: big, small, long, short; mẫu câu: My arms are long. My legs are short.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “My arms are long. My legs are short”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 4 “Our bodies” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Describing bodies”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 4 “Our bodies”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: big, small, long, short.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"My arms are long. My legs are short.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"My arms are long. My legs are short.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 4 “Our bodies” — Lesson 2 (Describing bodies) cho HS nghe mẫu câu “My arms are long. My legs are short” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ big, small, long, short vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “My arms are long. My legs are short”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong big, small, long, short mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":6,"tiet":3,"bai":"Unit 4 — Our bodies — Lesson 2 (Describing bodies) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết big, small, long, short; nghe hiểu mẫu câu \"My arms are long. My legs are short.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"My arms are long. My legs are short.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: big, small, long, short; mẫu câu: My arms are long. My legs are short.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Describing bodies” (Unit 4 “Our bodies”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 4 “Our bodies”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"My arms are long. My legs are short.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":6,"tiet":4,"bai":"Unit 4 — Our bodies — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our bodies\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 4; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 4 “Our bodies” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 4 “Our bodies”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 4 “Our bodies” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Our bodies.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 4 “Our bodies”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":7,"tiet":1,"bai":"Unit 4 — Our bodies — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our bodies\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 4; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 4 “Our bodies” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 4 “Our bodies”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 4 “Our bodies”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 4 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 4 “Our bodies” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Our bodies (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 4 “Our bodies” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Our bodies khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":7,"tiet":2,"bai":"Unit 5 — My hobbies — Lesson 1 (Talking about hobbies) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết hobby, drawing, singing; nghe hiểu mẫu câu \"What's your hobby? – It's drawing.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's your hobby? – It's drawing.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: hobby, drawing, singing; mẫu câu: What's your hobby? – It's drawing.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc hobby, drawing, singing, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 5 “My hobbies” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Talking about hobbies”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 5 “My hobbies”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: hobby, drawing, singing.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What's your hobby? – It's drawing.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What's your hobby? – It's drawing.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 5 “My hobbies” cho HS nghe người bản ngữ đọc hobby, drawing, singing; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt hobby, drawing, singing và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc hobby, drawing, singing, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 5 “My hobbies”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":7,"tiet":3,"bai":"Unit 5 — My hobbies — Lesson 1 (Talking about hobbies) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết hobby, drawing, singing; nghe hiểu mẫu câu \"What's your hobby? – It's drawing.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's your hobby? – It's drawing.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: hobby, drawing, singing; mẫu câu: What's your hobby? – It's drawing.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Talking about hobbies” (Unit 5 “My hobbies”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 5 “My hobbies”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What's your hobby? – It's drawing.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":7,"tiet":4,"bai":"Unit 5 — My hobbies — Lesson 2 (Likes about hobbies) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết like, dancing, cooking; nghe hiểu mẫu câu \"Do you like singing? – Yes, I do. / No, I don't.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Do you like singing? – Yes, I do. / No, I don't.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: like, dancing, cooking; mẫu câu: Do you like singing? – Yes, I do. / No, I don't.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Do you like singing? – Yes, I do. / No, I don't”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 5 “My hobbies” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Likes about hobbies”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 5 “My hobbies”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: like, dancing, cooking.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Do you like singing? – Yes, I do. / No, I don't.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Do you like singing? – Yes, I do. / No, I don't.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 5 “My hobbies” — Lesson 2 (Likes about hobbies) cho HS nghe mẫu câu “Do you like singing? – Yes, I do. / No, I don't” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ like, dancing, cooking vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Do you like singing? – Yes, I do. / No, I don't”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong like, dancing, cooking mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":8,"tiet":1,"bai":"Unit 5 — My hobbies — Lesson 2 (Likes about hobbies) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết like, dancing, cooking; nghe hiểu mẫu câu \"Do you like singing? – Yes, I do. / No, I don't.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Do you like singing? – Yes, I do. / No, I don't.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: like, dancing, cooking; mẫu câu: Do you like singing? – Yes, I do. / No, I don't.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Likes about hobbies” (Unit 5 “My hobbies”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 5 “My hobbies”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Do you like singing? – Yes, I do. / No, I don't.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":8,"tiet":2,"bai":"Unit 5 — My hobbies — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My hobbies\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 5; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 5 “My hobbies” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 5 “My hobbies”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 5 “My hobbies” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về My hobbies.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 5 “My hobbies”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":8,"tiet":3,"bai":"Unit 5 — My hobbies — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My hobbies\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 5; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 5 “My hobbies” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 5 “My hobbies”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 5 “My hobbies”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 5 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 5 “My hobbies” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về My hobbies (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 5 “My hobbies” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về My hobbies khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":8,"tiet":4,"bai":"Review 1 (Ôn tập – Nghe – Đọc)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 1–5.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.\n4. Tích hợp\n- Năng lực số 5.4 CB1a: Nhận ra được năng lực số của tôi cần được cải thiện hoặc cập nhật ở đâu: HS làm được bài ôn tương tác của “Review 1 (Ôn tập – Nghe – Đọc)” và tự biết mình còn yếu ở phần nào của Unit 1–5.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 1–5.\n- Nêu mục tiêu Review 1: củng cố kĩ năng Nghe và Đọc.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 1–5.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ bài tập tương tác có chấm tự động cho “Review 1 (Ôn tập – Nghe – Đọc)” với ngữ liệu Unit 1–5: nghe rồi chọn tranh, nối từ với hình, chọn câu trả lời đúng. Làm xong câu nào HS biết ngay đúng hay sai, tự đếm được mình còn yếu ở phần nghe hay phần đọc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở lại đúng đoạn audio của Unit 1–5 mà cả lớp làm sai nhiều nhất, cho nghe chậm từng câu; HS chỉ ra từ khoá mình đã nghe sót rồi làm lại câu đó.\n⚠ (Miền 4: An toàn) HS làm hết bài rồi mới xem đáp án, xem để hiểu chứ không phải để chép; máy chấm đúng sai chứ không chấm em giỏi hay kém, làm sai thì làm lại. Nếu làm bài trên máy tính bảng của lớp thì dùng đúng máy được phát, không mở sang trang khác; phần mềm hỏi tên thì chỉ gõ tên gọi ở nhà hoặc số thứ tự trong lớp, không gõ họ tên đầy đủ.","hs":"- HS làm được bài ôn tương tác của “Review 1 (Ôn tập – Nghe – Đọc)” và tự biết mình còn yếu ở phần nào của Unit 1–5.\n- HS nghe lại đoạn audio mình làm sai, chỉ ra từ khoá đã nghe sót và làm lại câu đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":9,"tiet":1,"bai":"Review 1 (Ôn tập – Nói – Viết)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 1–5.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 1–5.\n- Nêu mục tiêu Review 1: củng cố kĩ năng Nói và Viết.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 1–5.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":9,"tiet":2,"bai":"Review 1 (Ôn tập – Fun time & Củng cố)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 1–5.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS tham gia trò chơi ôn ngữ liệu Unit 1–5 trong “Review 1 (Ôn tập – Fun time & Củng cố)” và biết ngay mình còn nhớ được những từ nào.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 1–5.\n- Nêu mục tiêu Review 1: củng cố trò chơi ngôn ngữ, hệ thống hoá từ vựng – mẫu câu.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 1–5.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV tổ chức phần Fun time của “Review 1 (Ôn tập – Fun time & Củng cố)” bằng trò chơi ôn từ trên máy chiếu (lật thẻ tìm cặp từ – tranh, ô chữ, vòng quay chọn từ) với ngữ liệu Unit 1–5; các tổ thi tìm nhanh, máy giữ điểm và báo đúng sai ngay nên cả lớp nhìn thấy mình còn nhớ được bao nhiêu từ.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV thao tác cho cả lớp nghe một câu ôn tập của Unit 1–5 đọc bằng hai giọng: giọng người bản ngữ trong audio SGK và giọng do máy tự đọc; HS chỉ ra chỗ máy đọc đều đều, nối âm chưa tự nhiên, từ đó hiểu vì sao luyện phát âm vẫn phải nghe audio của SGK. HS chỉ nghe và nhận xét, không tự dùng công cụ này.\n⚠ (Miền 4: An toàn) GV là người mở trò chơi và mở công cụ đọc mẫu; HS ngồi tại chỗ, không tự vào máy của lớp. Chơi theo tổ thì thắng thua đều vui vẻ, không chê bạn đọc sai — trò chơi để ôn bài chứ không để so bì. Không nhập tên thật của HS vào phần mềm trò chơi trên mạng, chỉ dùng tên tổ hoặc số thứ tự.","hs":"- HS tham gia trò chơi ôn ngữ liệu Unit 1–5 trong “Review 1 (Ôn tập – Fun time & Củng cố)” và biết ngay mình còn nhớ được những từ nào.\n- HS chỉ ra được chỗ giọng máy đọc chưa tự nhiên so với giọng người bản ngữ trong audio SGK."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":9,"tiet":3,"bai":"Unit 6 — Our school — Lesson 1 (School places) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết school, library, gym; nghe hiểu mẫu câu \"This is my school. It's big.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my school. It's big.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: school, library, gym; mẫu câu: This is my school. It's big.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc school, library, gym, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 6 “Our school” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “School places”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 6 “Our school”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: school, library, gym.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"This is my school. It's big.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"This is my school. It's big.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 6 “Our school” cho HS nghe người bản ngữ đọc school, library, gym; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt school, library, gym và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc school, library, gym, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 6 “Our school”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":9,"tiet":4,"bai":"Unit 6 — Our school — Lesson 1 (School places) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết school, library, gym; nghe hiểu mẫu câu \"This is my school. It's big.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my school. It's big.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: school, library, gym; mẫu câu: This is my school. It's big.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “School places” (Unit 6 “Our school”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 6 “Our school”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"This is my school. It's big.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":10,"tiet":1,"bai":"Unit 6 — Our school — Lesson 2 (Describing school) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết new, old, big, small; nghe hiểu mẫu câu \"Is your school big? – Yes, it is.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Is your school big? – Yes, it is.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: new, old, big, small; mẫu câu: Is your school big? – Yes, it is.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Is your school big? – Yes, it is”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 6 “Our school” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Describing school”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 6 “Our school”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: new, old, big, small.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Is your school big? – Yes, it is.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Is your school big? – Yes, it is.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 6 “Our school” — Lesson 2 (Describing school) cho HS nghe mẫu câu “Is your school big? – Yes, it is” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ new, old, big, small vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Is your school big? – Yes, it is”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong new, old, big, small mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":10,"tiet":2,"bai":"Unit 6 — Our school — Lesson 2 (Describing school) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết new, old, big, small; nghe hiểu mẫu câu \"Is your school big? – Yes, it is.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Is your school big? – Yes, it is.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: new, old, big, small; mẫu câu: Is your school big? – Yes, it is.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Describing school” (Unit 6 “Our school”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 6 “Our school”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Is your school big? – Yes, it is.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":10,"tiet":3,"bai":"Unit 6 — Our school — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our school\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 6; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 6 “Our school” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 6 “Our school”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 6 “Our school” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Our school.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 6 “Our school”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":10,"tiet":4,"bai":"Unit 6 — Our school — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our school\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 6; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 6 “Our school” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 6 “Our school”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 6 “Our school”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 6 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 6 “Our school” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Our school (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 6 “Our school” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Our school khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":11,"tiet":1,"bai":"Unit 7 — Classroom instructions — Lesson 1 (Classroom commands) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết sit down, stand up, open; nghe hiểu mẫu câu \"Stand up, please. – OK.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Stand up, please. – OK.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: sit down, stand up, open; mẫu câu: Stand up, please. – OK.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc sit down, stand up, open, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 7 “Classroom instructions” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Classroom commands”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 7 “Classroom instructions”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: sit down, stand up, open.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Stand up, please. – OK.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Stand up, please. – OK.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 7 “Classroom instructions” cho HS nghe người bản ngữ đọc sit down, stand up, open; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt sit down, stand up, open và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc sit down, stand up, open, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 7 “Classroom instructions”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":11,"tiet":2,"bai":"Unit 7 — Classroom instructions — Lesson 1 (Classroom commands) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết sit down, stand up, open; nghe hiểu mẫu câu \"Stand up, please. – OK.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Stand up, please. – OK.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: sit down, stand up, open; mẫu câu: Stand up, please. – OK.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Classroom commands” (Unit 7 “Classroom instructions”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 7 “Classroom instructions”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Stand up, please. – OK.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":11,"tiet":3,"bai":"Unit 7 — Classroom instructions — Lesson 2 (Making requests) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết close, come, go, book; nghe hiểu mẫu câu \"Open your book, please.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Open your book, please.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: close, come, go, book; mẫu câu: Open your book, please.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Open your book, please”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 7 “Classroom instructions” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Making requests”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 7 “Classroom instructions”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: close, come, go, book.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Open your book, please.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Open your book, please.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 7 “Classroom instructions” — Lesson 2 (Making requests) cho HS nghe mẫu câu “Open your book, please” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ close, come, go, book vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Open your book, please”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong close, come, go, book mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":11,"tiet":4,"bai":"Unit 7 — Classroom instructions — Lesson 2 (Making requests) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết close, come, go, book; nghe hiểu mẫu câu \"Open your book, please.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Open your book, please.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: close, come, go, book; mẫu câu: Open your book, please.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Making requests” (Unit 7 “Classroom instructions”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 7 “Classroom instructions”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Open your book, please.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":12,"tiet":1,"bai":"Unit 7 — Classroom instructions — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Classroom instructions\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 7; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 7 “Classroom instructions” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 7 “Classroom instructions”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 7 “Classroom instructions” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Classroom instructions.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 7 “Classroom instructions”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":12,"tiet":2,"bai":"Unit 7 — Classroom instructions — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Classroom instructions\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 7; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 7 “Classroom instructions” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 7 “Classroom instructions”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 7 “Classroom instructions”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 7 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 7 “Classroom instructions” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Classroom instructions (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 7 “Classroom instructions” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Classroom instructions khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":12,"tiet":3,"bai":"Kiểm tra định kì giữa học kì I","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- kiểm tra đánh giá giữa học kì I (nghe, đọc, viết) theo Thông tư 27/2020/TT-BGDĐT; nội dung Unit 1–7.\n2. Năng lực chung: Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất: Chăm chỉ, tự tin, trung thực trong kiểm tra – đánh giá.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV ổn định lớp, tạo tâm lí thoải mái, tự tin trước khi làm bài.\n- Nhắc hình thức, thời gian và quy tắc làm bài kiểm tra; phát đề.","hs":"- HS chuẩn bị đồ dùng, giữ trật tự, lắng nghe hướng dẫn làm bài."},{"ten":"2. Nội dung chính","gv":"- GV tổ chức kiểm tra đánh giá giữa học kì I (nghe, đọc, viết) theo Thông tư 27/2020/TT-BGDĐT; nội dung Unit 1–7.","hs":"- HS thực hiện nhiệm vụ theo hướng dẫn."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập/làm bài, chữa và nhận xét.","hs":"- HS làm bài, tự đánh giá, rút kinh nghiệm."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":12,"tiet":4,"bai":"Unit 8 — My school things — Lesson 1 (School things) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết pen, pencil, ruler, book; nghe hiểu mẫu câu \"What's this? – It's a pen.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's this? – It's a pen.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: pen, pencil, ruler, book; mẫu câu: What's this? – It's a pen.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc pen, pencil, ruler, book, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 8 “My school things” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “School things”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 8 “My school things”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: pen, pencil, ruler, book.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What's this? – It's a pen.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What's this? – It's a pen.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 8 “My school things” cho HS nghe người bản ngữ đọc pen, pencil, ruler, book; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt pen, pencil, ruler, book và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc pen, pencil, ruler, book, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 8 “My school things”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":13,"tiet":1,"bai":"Unit 8 — My school things — Lesson 1 (School things) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết pen, pencil, ruler, book; nghe hiểu mẫu câu \"What's this? – It's a pen.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's this? – It's a pen.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: pen, pencil, ruler, book; mẫu câu: What's this? – It's a pen.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “School things” (Unit 8 “My school things”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 8 “My school things”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What's this? – It's a pen.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":13,"tiet":2,"bai":"Unit 8 — My school things — Lesson 2 (How many things) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết rubber, bag, how many; nghe hiểu mẫu câu \"How many pens? – Two pens.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How many pens? – Two pens.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: rubber, bag, how many; mẫu câu: How many pens? – Two pens.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “How many pens? – Two pens”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 8 “My school things” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “How many things”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 8 “My school things”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: rubber, bag, how many.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"How many pens? – Two pens.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"How many pens? – Two pens.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 8 “My school things” — Lesson 2 (How many things) cho HS nghe mẫu câu “How many pens? – Two pens” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ rubber, bag, how many vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “How many pens? – Two pens”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong rubber, bag, how many mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":13,"tiet":3,"bai":"Unit 8 — My school things — Lesson 2 (How many things) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết rubber, bag, how many; nghe hiểu mẫu câu \"How many pens? – Two pens.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How many pens? – Two pens.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: rubber, bag, how many; mẫu câu: How many pens? – Two pens.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “How many things” (Unit 8 “My school things”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 8 “My school things”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"How many pens? – Two pens.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":13,"tiet":4,"bai":"Unit 8 — My school things — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My school things\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 8; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 8 “My school things” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 8 “My school things”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 8 “My school things” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về My school things.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 8 “My school things”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":14,"tiet":1,"bai":"Unit 8 — My school things — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My school things\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 8; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 8 “My school things” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 8 “My school things”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 8 “My school things”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 8 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 8 “My school things” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về My school things (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 8 “My school things” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về My school things khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":14,"tiet":2,"bai":"Unit 9 — Colours — Lesson 1 (Naming colours) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết red, blue, green, yellow; nghe hiểu mẫu câu \"What colour is it? – It's red.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What colour is it? – It's red.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: red, blue, green, yellow; mẫu câu: What colour is it? – It's red.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc red, blue, green, yellow, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 9 “Colours” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Naming colours”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 9 “Colours”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: red, blue, green, yellow.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What colour is it? – It's red.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What colour is it? – It's red.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 9 “Colours” cho HS nghe người bản ngữ đọc red, blue, green, yellow; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt red, blue, green, yellow và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc red, blue, green, yellow, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 9 “Colours”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":14,"tiet":3,"bai":"Unit 9 — Colours — Lesson 1 (Naming colours) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết red, blue, green, yellow; nghe hiểu mẫu câu \"What colour is it? – It's red.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What colour is it? – It's red.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: red, blue, green, yellow; mẫu câu: What colour is it? – It's red.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Naming colours” (Unit 9 “Colours”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 9 “Colours”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What colour is it? – It's red.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":14,"tiet":4,"bai":"Unit 9 — Colours — Lesson 2 (Colours of things) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết black, white, orange, pink; nghe hiểu mẫu câu \"What colour is your bag? – It's blue.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What colour is your bag? – It's blue.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: black, white, orange, pink; mẫu câu: What colour is your bag? – It's blue.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “What colour is your bag? – It's blue”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 9 “Colours” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Colours of things”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 9 “Colours”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: black, white, orange, pink.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What colour is your bag? – It's blue.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What colour is your bag? – It's blue.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 9 “Colours” — Lesson 2 (Colours of things) cho HS nghe mẫu câu “What colour is your bag? – It's blue” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ black, white, orange, pink vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “What colour is your bag? – It's blue”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong black, white, orange, pink mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":15,"tiet":1,"bai":"Unit 9 — Colours — Lesson 2 (Colours of things) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết black, white, orange, pink; nghe hiểu mẫu câu \"What colour is your bag? – It's blue.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What colour is your bag? – It's blue.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: black, white, orange, pink; mẫu câu: What colour is your bag? – It's blue.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Colours of things” (Unit 9 “Colours”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 9 “Colours”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What colour is your bag? – It's blue.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":15,"tiet":2,"bai":"Unit 9 — Colours — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Colours\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 9; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 9 “Colours” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 9 “Colours”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 9 “Colours” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Colours.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 9 “Colours”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":15,"tiet":3,"bai":"Unit 9 — Colours — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Colours\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 9; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 9 “Colours” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 9 “Colours”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 9 “Colours”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 9 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 9 “Colours” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Colours (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 9 “Colours” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Colours khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":15,"tiet":4,"bai":"Unit 10 — Break time activities — Lesson 1 (Break time actions) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết skip, play, read, draw; nghe hiểu mẫu câu \"What do you do at break time? – I skip.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What do you do at break time? – I skip.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: skip, play, read, draw; mẫu câu: What do you do at break time? – I skip.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc skip, play, read, draw, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 10 “Break time activities” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Break time actions”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 10 “Break time activities”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: skip, play, read, draw.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What do you do at break time? – I skip.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What do you do at break time? – I skip.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 10 “Break time activities” cho HS nghe người bản ngữ đọc skip, play, read, draw; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt skip, play, read, draw và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc skip, play, read, draw, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 10 “Break time activities”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":16,"tiet":1,"bai":"Unit 10 — Break time activities — Lesson 1 (Break time actions) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết skip, play, read, draw; nghe hiểu mẫu câu \"What do you do at break time? – I skip.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What do you do at break time? – I skip.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: skip, play, read, draw; mẫu câu: What do you do at break time? – I skip.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Break time actions” (Unit 10 “Break time activities”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 10 “Break time activities”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What do you do at break time? – I skip.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":16,"tiet":2,"bai":"Unit 10 — Break time activities — Lesson 2 (Likes at break time) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết like, blind man's buff; nghe hiểu mẫu câu \"Do you like skipping? – Yes, I do.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Do you like skipping? – Yes, I do.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: like, blind man's buff; mẫu câu: Do you like skipping? – Yes, I do.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Do you like skipping? – Yes, I do”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 10 “Break time activities” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Likes at break time”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 10 “Break time activities”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: like, blind man's buff.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Do you like skipping? – Yes, I do.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Do you like skipping? – Yes, I do.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 10 “Break time activities” — Lesson 2 (Likes at break time) cho HS nghe mẫu câu “Do you like skipping? – Yes, I do” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ like, blind man's buff vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Do you like skipping? – Yes, I do”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong like, blind man's buff mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":16,"tiet":3,"bai":"Unit 10 — Break time activities — Lesson 2 (Likes at break time) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết like, blind man's buff; nghe hiểu mẫu câu \"Do you like skipping? – Yes, I do.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Do you like skipping? – Yes, I do.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: like, blind man's buff; mẫu câu: Do you like skipping? – Yes, I do.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Likes at break time” (Unit 10 “Break time activities”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 10 “Break time activities”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Do you like skipping? – Yes, I do.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":16,"tiet":4,"bai":"Unit 10 — Break time activities — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Break time activities\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 10; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 10 “Break time activities” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 10 “Break time activities”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 10 “Break time activities” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Break time activities.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 10 “Break time activities”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":17,"tiet":1,"bai":"Unit 10 — Break time activities — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Break time activities\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 10; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 10 “Break time activities” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 10 “Break time activities”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 10 “Break time activities”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 10 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 10 “Break time activities” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Break time activities (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 10 “Break time activities” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Break time activities khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":17,"tiet":2,"bai":"Review 2 (Ôn tập – Nghe – Đọc)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 6–10.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.\n4. Tích hợp\n- Năng lực số 5.4 CB1a: Nhận ra được năng lực số của tôi cần được cải thiện hoặc cập nhật ở đâu: HS làm được bài ôn tương tác của “Review 2 (Ôn tập – Nghe – Đọc)” và tự biết mình còn yếu ở phần nào của Unit 6–10.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 6–10.\n- Nêu mục tiêu Review 2: củng cố kĩ năng Nghe và Đọc.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 6–10.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ bài tập tương tác có chấm tự động cho “Review 2 (Ôn tập – Nghe – Đọc)” với ngữ liệu Unit 6–10: nghe rồi chọn tranh, nối từ với hình, chọn câu trả lời đúng. Làm xong câu nào HS biết ngay đúng hay sai, tự đếm được mình còn yếu ở phần nghe hay phần đọc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở lại đúng đoạn audio của Unit 6–10 mà cả lớp làm sai nhiều nhất, cho nghe chậm từng câu; HS chỉ ra từ khoá mình đã nghe sót rồi làm lại câu đó.\n⚠ (Miền 4: An toàn) HS làm hết bài rồi mới xem đáp án, xem để hiểu chứ không phải để chép; máy chấm đúng sai chứ không chấm em giỏi hay kém, làm sai thì làm lại. Nếu làm bài trên máy tính bảng của lớp thì dùng đúng máy được phát, không mở sang trang khác; phần mềm hỏi tên thì chỉ gõ tên gọi ở nhà hoặc số thứ tự trong lớp, không gõ họ tên đầy đủ.","hs":"- HS làm được bài ôn tương tác của “Review 2 (Ôn tập – Nghe – Đọc)” và tự biết mình còn yếu ở phần nào của Unit 6–10.\n- HS nghe lại đoạn audio mình làm sai, chỉ ra từ khoá đã nghe sót và làm lại câu đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":17,"tiet":3,"bai":"Review 2 (Ôn tập – Nói – Viết)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 6–10.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 6–10.\n- Nêu mục tiêu Review 2: củng cố kĩ năng Nói và Viết.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 6–10.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":17,"tiet":4,"bai":"Review 2 (Ôn tập – Fun time & Củng cố)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 6–10.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS tham gia trò chơi ôn ngữ liệu Unit 6–10 trong “Review 2 (Ôn tập – Fun time & Củng cố)” và biết ngay mình còn nhớ được những từ nào.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 6–10.\n- Nêu mục tiêu Review 2: củng cố trò chơi ngôn ngữ, hệ thống hoá từ vựng – mẫu câu.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 6–10.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV tổ chức phần Fun time của “Review 2 (Ôn tập – Fun time & Củng cố)” bằng trò chơi ôn từ trên máy chiếu (lật thẻ tìm cặp từ – tranh, ô chữ, vòng quay chọn từ) với ngữ liệu Unit 6–10; các tổ thi tìm nhanh, máy giữ điểm và báo đúng sai ngay nên cả lớp nhìn thấy mình còn nhớ được bao nhiêu từ.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV thao tác cho cả lớp nghe một câu ôn tập của Unit 6–10 đọc bằng hai giọng: giọng người bản ngữ trong audio SGK và giọng do máy tự đọc; HS chỉ ra chỗ máy đọc đều đều, nối âm chưa tự nhiên, từ đó hiểu vì sao luyện phát âm vẫn phải nghe audio của SGK. HS chỉ nghe và nhận xét, không tự dùng công cụ này.\n⚠ (Miền 4: An toàn) GV là người mở trò chơi và mở công cụ đọc mẫu; HS ngồi tại chỗ, không tự vào máy của lớp. Chơi theo tổ thì thắng thua đều vui vẻ, không chê bạn đọc sai — trò chơi để ôn bài chứ không để so bì. Không nhập tên thật của HS vào phần mềm trò chơi trên mạng, chỉ dùng tên tổ hoặc số thứ tự.","hs":"- HS tham gia trò chơi ôn ngữ liệu Unit 6–10 trong “Review 2 (Ôn tập – Fun time & Củng cố)” và biết ngay mình còn nhớ được những từ nào.\n- HS chỉ ra được chỗ giọng máy đọc chưa tự nhiên so với giọng người bản ngữ trong audio SGK."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":18,"tiet":1,"bai":"Ôn tập cuối học kì I","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- ôn tập tổng hợp từ vựng, mẫu câu Unit 1–10; luyện các kỹ năng nghe–nói–đọc–viết.\n2. Năng lực chung: Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất: Chăm chỉ, tự tin, trung thực trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.4 CB1a: Nhận ra được năng lực số của tôi cần được cải thiện hoặc cập nhật ở đâu: HS làm được bài ôn tương tác của “Ôn tập cuối học kì I” và tự biết mình còn yếu ở phần nào của Unit 1–10.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS chơi trò chơi/hỏi–đáp nhanh để huy động lại kiến thức đã học trong học kì.\n- Nêu mục tiêu tiết ôn tập, hệ thống các Unit trọng tâm chuẩn bị kiểm tra.","hs":"- HS tham gia, nhắc lại chủ đề – từ vựng; xác định nội dung cần ôn."},{"ten":"2. Nội dung chính","gv":"- GV tổ chức ôn tập tổng hợp từ vựng, mẫu câu Unit 1–10; luyện các kỹ năng nghe–nói–đọc–viết.","hs":"- HS thực hiện nhiệm vụ theo hướng dẫn."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập/làm bài, chữa và nhận xét.","hs":"- HS làm bài, tự đánh giá, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ bài tập tương tác có chấm tự động cho “Ôn tập cuối học kì I” với ngữ liệu Unit 1–10: nghe rồi chọn tranh, nối từ với hình, chọn câu trả lời đúng. Làm xong câu nào HS biết ngay đúng hay sai, tự đếm được mình còn yếu ở phần nghe hay phần đọc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở lại đúng đoạn audio của Unit 1–10 mà cả lớp làm sai nhiều nhất, cho nghe chậm từng câu; HS chỉ ra từ khoá mình đã nghe sót rồi làm lại câu đó.\n⚠ (Miền 4: An toàn) HS làm hết bài rồi mới xem đáp án, xem để hiểu chứ không phải để chép; máy chấm đúng sai chứ không chấm em giỏi hay kém, làm sai thì làm lại. Nếu làm bài trên máy tính bảng của lớp thì dùng đúng máy được phát, không mở sang trang khác; phần mềm hỏi tên thì chỉ gõ tên gọi ở nhà hoặc số thứ tự trong lớp, không gõ họ tên đầy đủ.","hs":"- HS làm được bài ôn tương tác của “Ôn tập cuối học kì I” và tự biết mình còn yếu ở phần nào của Unit 1–10.\n- HS nghe lại đoạn audio mình làm sai, chỉ ra từ khoá đã nghe sót và làm lại câu đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":18,"tiet":2,"bai":"Kiểm tra định kì cuối học kì I","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- kiểm tra đánh giá định kì cuối học kì I (nghe, đọc, viết, nói) theo Thông tư 27/2020/TT-BGDĐT.\n2. Năng lực chung: Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất: Chăm chỉ, tự tin, trung thực trong kiểm tra – đánh giá.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV ổn định lớp, tạo tâm lí thoải mái, tự tin trước khi làm bài.\n- Nhắc hình thức, thời gian và quy tắc làm bài kiểm tra; phát đề.","hs":"- HS chuẩn bị đồ dùng, giữ trật tự, lắng nghe hướng dẫn làm bài."},{"ten":"2. Nội dung chính","gv":"- GV tổ chức kiểm tra đánh giá định kì cuối học kì I (nghe, đọc, viết, nói) theo Thông tư 27/2020/TT-BGDĐT.","hs":"- HS thực hiện nhiệm vụ theo hướng dẫn."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập/làm bài, chữa và nhận xét.","hs":"- HS làm bài, tự đánh giá, rút kinh nghiệm."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":18,"tiet":3,"bai":"Chữa bài & củng cố sau kiểm tra HK I","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- chữa bài kiểm tra, củng cố kiến thức còn yếu; ôn lại phát âm và mẫu câu trọng tâm.\n2. Năng lực chung: Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất: Chăm chỉ, tự tin, trung thực trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe lại phát âm chuẩn của những từ mình làm sai trong “Chữa bài & củng cố sau kiểm tra HK I” và chép được vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV nhận xét chung kết quả kiểm tra, động viên tinh thần học tập.\n- Dẫn vào tiết chữa bài – củng cố những nội dung HS còn sai sót.","hs":"- HS lắng nghe, đối chiếu bài làm, ghi nhận phần cần sửa."},{"ten":"2. Nội dung chính","gv":"- GV tổ chức chữa bài kiểm tra, củng cố kiến thức còn yếu; ôn lại phát âm và mẫu câu trọng tâm.","hs":"- HS thực hiện nhiệm vụ theo hướng dẫn."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập/làm bài, chữa và nhận xét.","hs":"- HS làm bài, tự đánh giá, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) Sau khi trả bài trong tiết “Chữa bài & củng cố sau kiểm tra HK I”, GV mở lại đúng những đoạn audio và những từ cả lớp sai nhiều nhất; GV gõ từng từ vào từ điển điện tử có nút phát âm, bấm loa cho HS nghe lại 2-3 lần rồi HS chép từ đó vào sổ tay từ vựng viết tay của mình.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV thao tác cho HS xem: gõ một câu tiếng Việt trong bài vào công cụ dịch tự động, máy trả về một câu tiếng Anh chưa đúng với mẫu câu các em đã học; GV cùng cả lớp sửa lại theo đúng mẫu câu trong SGK. HS thấy được máy dịch chỉ để tham khảo, chưa thay được việc mình học thuộc mẫu câu.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và mở công cụ dịch trên máy của lớp; HS lớp 3 chưa tự dùng công cụ dịch để làm bài. Không chụp bài kiểm tra của mình hay của bạn gửi ra ngoài lớp; điểm số và bài làm của mỗi bạn là chuyện riêng, không đem ra chê cười. Sổ tay từ vựng HS tự chép tay để nhớ mặt chữ.","hs":"- HS nghe lại phát âm chuẩn của những từ mình làm sai trong “Chữa bài & củng cố sau kiểm tra HK I” và chép được vào sổ tay từ vựng.\n- HS nêu được vì sao câu do máy dịch chưa dùng được ngay mà phải sửa lại theo mẫu câu đã học."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":18,"tiet":4,"bai":"Unit 11 — My family — Lesson 1 (Family members) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết father, mother, brother; nghe hiểu mẫu câu \"This is my father.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my father.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: father, mother, brother; mẫu câu: This is my father.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc father, mother, brother, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 11 “My family” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Family members”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 11 “My family”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: father, mother, brother.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"This is my father.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"This is my father.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 11 “My family” cho HS nghe người bản ngữ đọc father, mother, brother; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt father, mother, brother và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc father, mother, brother, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 11 “My family”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":19,"tiet":1,"bai":"Unit 11 — My family — Lesson 1 (Family members) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết father, mother, brother; nghe hiểu mẫu câu \"This is my father.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my father.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: father, mother, brother; mẫu câu: This is my father.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Family members” (Unit 11 “My family”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 11 “My family”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"This is my father.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":19,"tiet":2,"bai":"Unit 11 — My family — Lesson 2 (Who's this?) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết sister, grandpa, grandma; nghe hiểu mẫu câu \"Who's this? – This is my mother.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Who's this? – This is my mother.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: sister, grandpa, grandma; mẫu câu: Who's this? – This is my mother.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Who's this? – This is my mother”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 11 “My family” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Who's this?”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 11 “My family”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: sister, grandpa, grandma.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Who's this? – This is my mother.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Who's this? – This is my mother.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 11 “My family” — Lesson 2 (Who's this?) cho HS nghe mẫu câu “Who's this? – This is my mother” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ sister, grandpa, grandma vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Who's this? – This is my mother”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong sister, grandpa, grandma mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":19,"tiet":3,"bai":"Unit 11 — My family — Lesson 2 (Who's this?) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết sister, grandpa, grandma; nghe hiểu mẫu câu \"Who's this? – This is my mother.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Who's this? – This is my mother.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: sister, grandpa, grandma; mẫu câu: Who's this? – This is my mother.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Who's this?” (Unit 11 “My family”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 11 “My family”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Who's this? – This is my mother.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":19,"tiet":4,"bai":"Unit 11 — My family — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My family\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 11; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 11 “My family” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 11 “My family”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 11 “My family” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về My family.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 11 “My family”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":20,"tiet":1,"bai":"Unit 11 — My family — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My family\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 11; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 11 “My family” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 11 “My family”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 11 “My family”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 11 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 11 “My family” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về My family (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 11 “My family” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về My family khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":20,"tiet":2,"bai":"Unit 12 — Jobs — Lesson 1 (Naming jobs) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết teacher, doctor, farmer; nghe hiểu mẫu câu \"What's your father's job? – He's a doctor.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's your father's job? – He's a doctor.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: teacher, doctor, farmer; mẫu câu: What's your father's job? – He's a doctor.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc teacher, doctor, farmer, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 12 “Jobs” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Naming jobs”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 12 “Jobs”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: teacher, doctor, farmer.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What's your father's job? – He's a doctor.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What's your father's job? – He's a doctor.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 12 “Jobs” cho HS nghe người bản ngữ đọc teacher, doctor, farmer; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt teacher, doctor, farmer và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc teacher, doctor, farmer, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 12 “Jobs”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":20,"tiet":3,"bai":"Unit 12 — Jobs — Lesson 1 (Naming jobs) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết teacher, doctor, farmer; nghe hiểu mẫu câu \"What's your father's job? – He's a doctor.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's your father's job? – He's a doctor.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: teacher, doctor, farmer; mẫu câu: What's your father's job? – He's a doctor.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Naming jobs” (Unit 12 “Jobs”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 12 “Jobs”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What's your father's job? – He's a doctor.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":20,"tiet":4,"bai":"Unit 12 — Jobs — Lesson 2 (Talking about jobs) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết nurse, worker, driver; nghe hiểu mẫu câu \"Is she a teacher? – Yes, she is.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Is she a teacher? – Yes, she is.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: nurse, worker, driver; mẫu câu: Is she a teacher? – Yes, she is.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Is she a teacher? – Yes, she is”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 12 “Jobs” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Talking about jobs”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 12 “Jobs”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: nurse, worker, driver.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Is she a teacher? – Yes, she is.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Is she a teacher? – Yes, she is.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 12 “Jobs” — Lesson 2 (Talking about jobs) cho HS nghe mẫu câu “Is she a teacher? – Yes, she is” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ nurse, worker, driver vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Is she a teacher? – Yes, she is”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong nurse, worker, driver mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":21,"tiet":1,"bai":"Unit 12 — Jobs — Lesson 2 (Talking about jobs) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết nurse, worker, driver; nghe hiểu mẫu câu \"Is she a teacher? – Yes, she is.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Is she a teacher? – Yes, she is.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: nurse, worker, driver; mẫu câu: Is she a teacher? – Yes, she is.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Talking about jobs” (Unit 12 “Jobs”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 12 “Jobs”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Is she a teacher? – Yes, she is.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":21,"tiet":2,"bai":"Unit 12 — Jobs — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Jobs\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 12; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 12 “Jobs” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 12 “Jobs”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 12 “Jobs” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Jobs.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 12 “Jobs”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":21,"tiet":3,"bai":"Unit 12 — Jobs — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Jobs\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 12; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 12 “Jobs” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 12 “Jobs”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 12 “Jobs”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 12 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 12 “Jobs” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Jobs (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 12 “Jobs” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Jobs khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":21,"tiet":4,"bai":"Unit 13 — My house — Lesson 1 (Rooms in a house) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết house, kitchen, bedroom; nghe hiểu mẫu câu \"This is my house. It has a kitchen.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my house. It has a kitchen.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: house, kitchen, bedroom; mẫu câu: This is my house. It has a kitchen.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc house, kitchen, bedroom, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 13 “My house” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Rooms in a house”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 13 “My house”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: house, kitchen, bedroom.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"This is my house. It has a kitchen.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"This is my house. It has a kitchen.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 13 “My house” cho HS nghe người bản ngữ đọc house, kitchen, bedroom; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt house, kitchen, bedroom và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc house, kitchen, bedroom, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 13 “My house”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":22,"tiet":1,"bai":"Unit 13 — My house — Lesson 1 (Rooms in a house) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết house, kitchen, bedroom; nghe hiểu mẫu câu \"This is my house. It has a kitchen.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my house. It has a kitchen.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: house, kitchen, bedroom; mẫu câu: This is my house. It has a kitchen.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Rooms in a house” (Unit 13 “My house”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 13 “My house”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"This is my house. It has a kitchen.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":22,"tiet":2,"bai":"Unit 13 — My house — Lesson 2 (Where is it?) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết living room, bathroom, garden; nghe hiểu mẫu câu \"Is there a garden? – Yes, there is.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Is there a garden? – Yes, there is.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: living room, bathroom, garden; mẫu câu: Is there a garden? – Yes, there is.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Is there a garden? – Yes, there is”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 13 “My house” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Where is it?”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 13 “My house”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: living room, bathroom, garden.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Is there a garden? – Yes, there is.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Is there a garden? – Yes, there is.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 13 “My house” — Lesson 2 (Where is it?) cho HS nghe mẫu câu “Is there a garden? – Yes, there is” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ living room, bathroom, garden vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Is there a garden? – Yes, there is”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong living room, bathroom, garden mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":22,"tiet":3,"bai":"Unit 13 — My house — Lesson 2 (Where is it?) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết living room, bathroom, garden; nghe hiểu mẫu câu \"Is there a garden? – Yes, there is.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Is there a garden? – Yes, there is.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: living room, bathroom, garden; mẫu câu: Is there a garden? – Yes, there is.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Where is it?” (Unit 13 “My house”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 13 “My house”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Is there a garden? – Yes, there is.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":22,"tiet":4,"bai":"Unit 13 — My house — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My house\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 13; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 13 “My house” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 13 “My house”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 13 “My house” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về My house.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 13 “My house”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":23,"tiet":1,"bai":"Unit 13 — My house — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My house\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 13; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 13 “My house” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 13 “My house”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 13 “My house”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 13 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 13 “My house” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về My house (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 13 “My house” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về My house khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":23,"tiet":2,"bai":"Unit 14 — My bedroom — Lesson 1 (Bedroom furniture) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết bed, table, chair, desk; nghe hiểu mẫu câu \"There's a bed in my bedroom.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"There's a bed in my bedroom.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: bed, table, chair, desk; mẫu câu: There's a bed in my bedroom.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc bed, table, chair, desk, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 14 “My bedroom” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Bedroom furniture”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 14 “My bedroom”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: bed, table, chair, desk.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"There's a bed in my bedroom.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"There's a bed in my bedroom.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 14 “My bedroom” cho HS nghe người bản ngữ đọc bed, table, chair, desk; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt bed, table, chair, desk và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc bed, table, chair, desk, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 14 “My bedroom”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":23,"tiet":3,"bai":"Unit 14 — My bedroom — Lesson 1 (Bedroom furniture) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết bed, table, chair, desk; nghe hiểu mẫu câu \"There's a bed in my bedroom.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"There's a bed in my bedroom.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: bed, table, chair, desk; mẫu câu: There's a bed in my bedroom.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Bedroom furniture” (Unit 14 “My bedroom”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 14 “My bedroom”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"There's a bed in my bedroom.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":23,"tiet":4,"bai":"Unit 14 — My bedroom — Lesson 2 (How many pieces) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết wardrobe, lamp, how many; nghe hiểu mẫu câu \"How many chairs are there? – Two.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How many chairs are there? – Two.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: wardrobe, lamp, how many; mẫu câu: How many chairs are there? – Two.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “How many chairs are there? – Two”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 14 “My bedroom” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “How many pieces”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 14 “My bedroom”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: wardrobe, lamp, how many.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"How many chairs are there? – Two.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"How many chairs are there? – Two.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 14 “My bedroom” — Lesson 2 (How many pieces) cho HS nghe mẫu câu “How many chairs are there? – Two” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ wardrobe, lamp, how many vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “How many chairs are there? – Two”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong wardrobe, lamp, how many mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":24,"tiet":1,"bai":"Unit 14 — My bedroom — Lesson 2 (How many pieces) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết wardrobe, lamp, how many; nghe hiểu mẫu câu \"How many chairs are there? – Two.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How many chairs are there? – Two.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: wardrobe, lamp, how many; mẫu câu: How many chairs are there? – Two.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “How many pieces” (Unit 14 “My bedroom”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 14 “My bedroom”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"How many chairs are there? – Two.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":24,"tiet":2,"bai":"Unit 14 — My bedroom — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My bedroom\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 14; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 14 “My bedroom” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 14 “My bedroom”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 14 “My bedroom” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về My bedroom.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 14 “My bedroom”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":24,"tiet":3,"bai":"Unit 14 — My bedroom — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My bedroom\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 14; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 14 “My bedroom” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 14 “My bedroom”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 14 “My bedroom”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 14 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 14 “My bedroom” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về My bedroom (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 14 “My bedroom” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về My bedroom khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":24,"tiet":4,"bai":"Unit 15 — At the dining table — Lesson 1 (Food & drinks) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết rice, fish, chicken, milk; nghe hiểu mẫu câu \"What would you like? – Some rice, please.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What would you like? – Some rice, please.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: rice, fish, chicken, milk; mẫu câu: What would you like? – Some rice, please.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc rice, fish, chicken, milk, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 15 “At the dining table” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Food & drinks”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 15 “At the dining table”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: rice, fish, chicken, milk.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What would you like? – Some rice, please.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What would you like? – Some rice, please.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 15 “At the dining table” cho HS nghe người bản ngữ đọc rice, fish, chicken, milk; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt rice, fish, chicken, milk và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc rice, fish, chicken, milk, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 15 “At the dining table”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":25,"tiet":1,"bai":"Unit 15 — At the dining table — Lesson 1 (Food & drinks) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết rice, fish, chicken, milk; nghe hiểu mẫu câu \"What would you like? – Some rice, please.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What would you like? – Some rice, please.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: rice, fish, chicken, milk; mẫu câu: What would you like? – Some rice, please.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Food & drinks” (Unit 15 “At the dining table”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 15 “At the dining table”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What would you like? – Some rice, please.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":25,"tiet":2,"bai":"Unit 15 — At the dining table — Lesson 2 (Would you like…?) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết bread, water, juice, some; nghe hiểu mẫu câu \"Would you like some milk? – Yes, please.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Would you like some milk? – Yes, please.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: bread, water, juice, some; mẫu câu: Would you like some milk? – Yes, please.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Would you like some milk? – Yes, please”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 15 “At the dining table” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Would you like…?”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 15 “At the dining table”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: bread, water, juice, some.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Would you like some milk? – Yes, please.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Would you like some milk? – Yes, please.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 15 “At the dining table” — Lesson 2 (Would you like…?) cho HS nghe mẫu câu “Would you like some milk? – Yes, please” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ bread, water, juice, some vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Would you like some milk? – Yes, please”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong bread, water, juice, some mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":25,"tiet":3,"bai":"Unit 15 — At the dining table — Lesson 2 (Would you like…?) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết bread, water, juice, some; nghe hiểu mẫu câu \"Would you like some milk? – Yes, please.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Would you like some milk? – Yes, please.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: bread, water, juice, some; mẫu câu: Would you like some milk? – Yes, please.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Would you like…?” (Unit 15 “At the dining table”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 15 “At the dining table”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Would you like some milk? – Yes, please.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":25,"tiet":4,"bai":"Unit 15 — At the dining table — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"At the dining table\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 15; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 15 “At the dining table” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 15 “At the dining table”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 15 “At the dining table” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về At the dining table.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 15 “At the dining table”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":26,"tiet":1,"bai":"Unit 15 — At the dining table — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"At the dining table\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 15; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 15 “At the dining table” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 15 “At the dining table”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 15 “At the dining table”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 15 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 15 “At the dining table” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về At the dining table (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 15 “At the dining table” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về At the dining table khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":26,"tiet":2,"bai":"Review 3 (Ôn tập – Nghe – Đọc)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 11–15.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.\n4. Tích hợp\n- Năng lực số 5.4 CB1a: Nhận ra được năng lực số của tôi cần được cải thiện hoặc cập nhật ở đâu: HS làm được bài ôn tương tác của “Review 3 (Ôn tập – Nghe – Đọc)” và tự biết mình còn yếu ở phần nào của Unit 11–15.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 11–15.\n- Nêu mục tiêu Review 3: củng cố kĩ năng Nghe và Đọc.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 11–15.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ bài tập tương tác có chấm tự động cho “Review 3 (Ôn tập – Nghe – Đọc)” với ngữ liệu Unit 11–15: nghe rồi chọn tranh, nối từ với hình, chọn câu trả lời đúng. Làm xong câu nào HS biết ngay đúng hay sai, tự đếm được mình còn yếu ở phần nghe hay phần đọc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở lại đúng đoạn audio của Unit 11–15 mà cả lớp làm sai nhiều nhất, cho nghe chậm từng câu; HS chỉ ra từ khoá mình đã nghe sót rồi làm lại câu đó.\n⚠ (Miền 4: An toàn) HS làm hết bài rồi mới xem đáp án, xem để hiểu chứ không phải để chép; máy chấm đúng sai chứ không chấm em giỏi hay kém, làm sai thì làm lại. Nếu làm bài trên máy tính bảng của lớp thì dùng đúng máy được phát, không mở sang trang khác; phần mềm hỏi tên thì chỉ gõ tên gọi ở nhà hoặc số thứ tự trong lớp, không gõ họ tên đầy đủ.","hs":"- HS làm được bài ôn tương tác của “Review 3 (Ôn tập – Nghe – Đọc)” và tự biết mình còn yếu ở phần nào của Unit 11–15.\n- HS nghe lại đoạn audio mình làm sai, chỉ ra từ khoá đã nghe sót và làm lại câu đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":26,"tiet":3,"bai":"Review 3 (Ôn tập – Nói – Viết)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 11–15.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 11–15.\n- Nêu mục tiêu Review 3: củng cố kĩ năng Nói và Viết.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 11–15.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":26,"tiet":4,"bai":"Review 3 (Ôn tập – Fun time & Củng cố)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 11–15.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS tham gia trò chơi ôn ngữ liệu Unit 11–15 trong “Review 3 (Ôn tập – Fun time & Củng cố)” và biết ngay mình còn nhớ được những từ nào.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 11–15.\n- Nêu mục tiêu Review 3: củng cố trò chơi ngôn ngữ, hệ thống hoá từ vựng – mẫu câu.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 11–15.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV tổ chức phần Fun time của “Review 3 (Ôn tập – Fun time & Củng cố)” bằng trò chơi ôn từ trên máy chiếu (lật thẻ tìm cặp từ – tranh, ô chữ, vòng quay chọn từ) với ngữ liệu Unit 11–15; các tổ thi tìm nhanh, máy giữ điểm và báo đúng sai ngay nên cả lớp nhìn thấy mình còn nhớ được bao nhiêu từ.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV thao tác cho cả lớp nghe một câu ôn tập của Unit 11–15 đọc bằng hai giọng: giọng người bản ngữ trong audio SGK và giọng do máy tự đọc; HS chỉ ra chỗ máy đọc đều đều, nối âm chưa tự nhiên, từ đó hiểu vì sao luyện phát âm vẫn phải nghe audio của SGK. HS chỉ nghe và nhận xét, không tự dùng công cụ này.\n⚠ (Miền 4: An toàn) GV là người mở trò chơi và mở công cụ đọc mẫu; HS ngồi tại chỗ, không tự vào máy của lớp. Chơi theo tổ thì thắng thua đều vui vẻ, không chê bạn đọc sai — trò chơi để ôn bài chứ không để so bì. Không nhập tên thật của HS vào phần mềm trò chơi trên mạng, chỉ dùng tên tổ hoặc số thứ tự.","hs":"- HS tham gia trò chơi ôn ngữ liệu Unit 11–15 trong “Review 3 (Ôn tập – Fun time & Củng cố)” và biết ngay mình còn nhớ được những từ nào.\n- HS chỉ ra được chỗ giọng máy đọc chưa tự nhiên so với giọng người bản ngữ trong audio SGK."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":27,"tiet":1,"bai":"Unit 16 — My pets — Lesson 1 (Naming pets) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết pet, cat, dog, fish, bird; nghe hiểu mẫu câu \"I have a cat. Do you have a pet?\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"I have a cat. Do you have a pet?\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: pet, cat, dog, fish, bird; mẫu câu: I have a cat. Do you have a pet?\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc pet, cat, dog, fish, bird, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 16 “My pets” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Naming pets”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 16 “My pets”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: pet, cat, dog, fish, bird.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"I have a cat. Do you have a pet?\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"I have a cat. Do you have a pet?\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 16 “My pets” cho HS nghe người bản ngữ đọc pet, cat, dog, fish, bird; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt pet, cat, dog, fish, bird và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc pet, cat, dog, fish, bird, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 16 “My pets”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":27,"tiet":2,"bai":"Unit 16 — My pets — Lesson 1 (Naming pets) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết pet, cat, dog, fish, bird; nghe hiểu mẫu câu \"I have a cat. Do you have a pet?\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"I have a cat. Do you have a pet?\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: pet, cat, dog, fish, bird; mẫu câu: I have a cat. Do you have a pet?\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Naming pets” (Unit 16 “My pets”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 16 “My pets”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"I have a cat. Do you have a pet?\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":27,"tiet":3,"bai":"Unit 16 — My pets — Lesson 2 (How many pets) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết rabbit, parrot, how many; nghe hiểu mẫu câu \"How many cats do you have? – Two cats.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How many cats do you have? – Two cats.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: rabbit, parrot, how many; mẫu câu: How many cats do you have? – Two cats.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “How many cats do you have? – Two cats”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 16 “My pets” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “How many pets”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 16 “My pets”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: rabbit, parrot, how many.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"How many cats do you have? – Two cats.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"How many cats do you have? – Two cats.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 16 “My pets” — Lesson 2 (How many pets) cho HS nghe mẫu câu “How many cats do you have? – Two cats” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ rabbit, parrot, how many vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “How many cats do you have? – Two cats”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong rabbit, parrot, how many mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":27,"tiet":4,"bai":"Unit 16 — My pets — Lesson 2 (How many pets) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết rabbit, parrot, how many; nghe hiểu mẫu câu \"How many cats do you have? – Two cats.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"How many cats do you have? – Two cats.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: rabbit, parrot, how many; mẫu câu: How many cats do you have? – Two cats.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “How many pets” (Unit 16 “My pets”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 16 “My pets”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"How many cats do you have? – Two cats.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":28,"tiet":1,"bai":"Unit 16 — My pets — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My pets\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 16; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 16 “My pets” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 16 “My pets”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 16 “My pets” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về My pets.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 16 “My pets”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":28,"tiet":2,"bai":"Unit 16 — My pets — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"My pets\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 16; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 16 “My pets” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 16 “My pets”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 16 “My pets”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 16 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 16 “My pets” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về My pets (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 16 “My pets” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về My pets khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":28,"tiet":3,"bai":"Unit 17 — Our toys — Lesson 1 (Naming toys) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết toy, car, ball, doll, kite; nghe hiểu mẫu câu \"This is my toy car.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my toy car.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: toy, car, ball, doll, kite; mẫu câu: This is my toy car.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc toy, car, ball, doll, kite, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 17 “Our toys” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Naming toys”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 17 “Our toys”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: toy, car, ball, doll, kite.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"This is my toy car.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"This is my toy car.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 17 “Our toys” cho HS nghe người bản ngữ đọc toy, car, ball, doll, kite; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt toy, car, ball, doll, kite và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc toy, car, ball, doll, kite, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 17 “Our toys”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":28,"tiet":4,"bai":"Unit 17 — Our toys — Lesson 1 (Naming toys) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết toy, car, ball, doll, kite; nghe hiểu mẫu câu \"This is my toy car.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"This is my toy car.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: toy, car, ball, doll, kite; mẫu câu: This is my toy car.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Naming toys” (Unit 17 “Our toys”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 17 “Our toys”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"This is my toy car.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":29,"tiet":1,"bai":"Unit 17 — Our toys — Lesson 2 (Whose toy is it?) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết robot, plane, teddy bear; nghe hiểu mẫu câu \"Is this your ball? – Yes, it is.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Is this your ball? – Yes, it is.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: robot, plane, teddy bear; mẫu câu: Is this your ball? – Yes, it is.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Is this your ball? – Yes, it is”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 17 “Our toys” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Whose toy is it?”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 17 “Our toys”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: robot, plane, teddy bear.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Is this your ball? – Yes, it is.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Is this your ball? – Yes, it is.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 17 “Our toys” — Lesson 2 (Whose toy is it?) cho HS nghe mẫu câu “Is this your ball? – Yes, it is” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ robot, plane, teddy bear vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Is this your ball? – Yes, it is”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong robot, plane, teddy bear mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":29,"tiet":2,"bai":"Unit 17 — Our toys — Lesson 2 (Whose toy is it?) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết robot, plane, teddy bear; nghe hiểu mẫu câu \"Is this your ball? – Yes, it is.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Is this your ball? – Yes, it is.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: robot, plane, teddy bear; mẫu câu: Is this your ball? – Yes, it is.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Whose toy is it?” (Unit 17 “Our toys”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 17 “Our toys”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Is this your ball? – Yes, it is.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":29,"tiet":3,"bai":"Unit 17 — Our toys — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our toys\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 17; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 17 “Our toys” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 17 “Our toys”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 17 “Our toys” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Our toys.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 17 “Our toys”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":29,"tiet":4,"bai":"Unit 17 — Our toys — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Our toys\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 17; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 17 “Our toys” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 17 “Our toys”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 17 “Our toys”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 17 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 17 “Our toys” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Our toys (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 17 “Our toys” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Our toys khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":30,"tiet":1,"bai":"Unit 18 — Playing and doing — Lesson 1 (Present continuous) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết playing, reading, singing; nghe hiểu mẫu câu \"What are you doing? – I'm playing.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What are you doing? – I'm playing.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: playing, reading, singing; mẫu câu: What are you doing? – I'm playing.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc playing, reading, singing, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 18 “Playing and doing” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Present continuous”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 18 “Playing and doing”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: playing, reading, singing.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What are you doing? – I'm playing.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What are you doing? – I'm playing.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 18 “Playing and doing” cho HS nghe người bản ngữ đọc playing, reading, singing; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt playing, reading, singing và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc playing, reading, singing, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 18 “Playing and doing”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":30,"tiet":2,"bai":"Unit 18 — Playing and doing — Lesson 1 (Present continuous) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết playing, reading, singing; nghe hiểu mẫu câu \"What are you doing? – I'm playing.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What are you doing? – I'm playing.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: playing, reading, singing; mẫu câu: What are you doing? – I'm playing.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Present continuous” (Unit 18 “Playing and doing”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 18 “Playing and doing”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What are you doing? – I'm playing.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":30,"tiet":3,"bai":"Unit 18 — Playing and doing — Lesson 2 (What is he/she doing?) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết writing, drawing, dancing; nghe hiểu mẫu câu \"What's she doing? – She's reading.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's she doing? – She's reading.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: writing, drawing, dancing; mẫu câu: What's she doing? – She's reading.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “What's she doing? – She's reading”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 18 “Playing and doing” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “What is he/she doing?”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 18 “Playing and doing”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: writing, drawing, dancing.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What's she doing? – She's reading.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What's she doing? – She's reading.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 18 “Playing and doing” — Lesson 2 (What is he/she doing?) cho HS nghe mẫu câu “What's she doing? – She's reading” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ writing, drawing, dancing vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “What's she doing? – She's reading”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong writing, drawing, dancing mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":30,"tiet":4,"bai":"Unit 18 — Playing and doing — Lesson 2 (What is he/she doing?) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết writing, drawing, dancing; nghe hiểu mẫu câu \"What's she doing? – She's reading.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What's she doing? – She's reading.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: writing, drawing, dancing; mẫu câu: What's she doing? – She's reading.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “What is he/she doing?” (Unit 18 “Playing and doing”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 18 “Playing and doing”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What's she doing? – She's reading.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":31,"tiet":1,"bai":"Unit 18 — Playing and doing — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Playing and doing\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 18; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 18 “Playing and doing” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 18 “Playing and doing”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 18 “Playing and doing” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Playing and doing.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 18 “Playing and doing”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":31,"tiet":2,"bai":"Unit 18 — Playing and doing — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Playing and doing\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 18; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 18 “Playing and doing” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 18 “Playing and doing”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 18 “Playing and doing”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 18 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 18 “Playing and doing” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Playing and doing (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 18 “Playing and doing” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Playing and doing khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":31,"tiet":3,"bai":"Unit 19 — Outdoor activities — Lesson 1 (Outdoor actions) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết cycling, fishing, flying a kite; nghe hiểu mẫu câu \"I like cycling in the park.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"I like cycling in the park.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: cycling, fishing, flying a kite; mẫu câu: I like cycling in the park.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc cycling, fishing, flying a kite, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 19 “Outdoor activities” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Outdoor actions”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 19 “Outdoor activities”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: cycling, fishing, flying a kite.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"I like cycling in the park.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"I like cycling in the park.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 19 “Outdoor activities” cho HS nghe người bản ngữ đọc cycling, fishing, flying a kite; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt cycling, fishing, flying a kite và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc cycling, fishing, flying a kite, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 19 “Outdoor activities”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":31,"tiet":4,"bai":"Unit 19 — Outdoor activities — Lesson 1 (Outdoor actions) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết cycling, fishing, flying a kite; nghe hiểu mẫu câu \"I like cycling in the park.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"I like cycling in the park.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: cycling, fishing, flying a kite; mẫu câu: I like cycling in the park.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Outdoor actions” (Unit 19 “Outdoor activities”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 19 “Outdoor activities”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"I like cycling in the park.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":32,"tiet":1,"bai":"Unit 19 — Outdoor activities — Lesson 2 (Let's…) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết swimming, camping, let's; nghe hiểu mẫu câu \"Let's go cycling. – Great idea!\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Let's go cycling. – Great idea!\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: swimming, camping, let's; mẫu câu: Let's go cycling. – Great idea!\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “Let's go cycling. – Great idea!”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 19 “Outdoor activities” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Let's…”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 19 “Outdoor activities”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: swimming, camping, let's.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Let's go cycling. – Great idea!\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Let's go cycling. – Great idea!\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 19 “Outdoor activities” — Lesson 2 (Let's…) cho HS nghe mẫu câu “Let's go cycling. – Great idea!” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ swimming, camping, let's vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “Let's go cycling. – Great idea!”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong swimming, camping, let's mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":32,"tiet":2,"bai":"Unit 19 — Outdoor activities — Lesson 2 (Let's…) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết swimming, camping, let's; nghe hiểu mẫu câu \"Let's go cycling. – Great idea!\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Let's go cycling. – Great idea!\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: swimming, camping, let's; mẫu câu: Let's go cycling. – Great idea!\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Let's…” (Unit 19 “Outdoor activities”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 19 “Outdoor activities”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Let's go cycling. – Great idea!\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":32,"tiet":3,"bai":"Unit 19 — Outdoor activities — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Outdoor activities\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 19; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 19 “Outdoor activities” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 19 “Outdoor activities”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 19 “Outdoor activities” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về Outdoor activities.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 19 “Outdoor activities”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":32,"tiet":4,"bai":"Unit 19 — Outdoor activities — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"Outdoor activities\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 19; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 19 “Outdoor activities” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 19 “Outdoor activities”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 19 “Outdoor activities”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 19 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 19 “Outdoor activities” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về Outdoor activities (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 19 “Outdoor activities” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về Outdoor activities khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":33,"tiet":1,"bai":"Unit 20 — At the zoo — Lesson 1 (Zoo animals) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết zoo, tiger, monkey, bear; nghe hiểu mẫu câu \"Look at the tiger! It's big.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Look at the tiger! It's big.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: zoo, tiger, monkey, bear; mẫu câu: Look at the tiger! It's big.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe giọng người bản ngữ đọc zoo, tiger, monkey, bear, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 20 “At the zoo” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Zoo animals”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 20 “At the zoo”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: zoo, tiger, monkey, bear.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"Look at the tiger! It's big.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"Look at the tiger! It's big.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở tệp audio phần Look, listen and repeat của Unit 20 “At the zoo” cho HS nghe người bản ngữ đọc zoo, tiger, monkey, bear; GV bấm dừng sau từng từ và cho nghe lại 2-3 lần đúng những từ HS đọc chưa đúng — cách dừng, tua lại từng từ này chỉ làm được với bản ghi âm, GV đọc mẫu bằng giọng của mình không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở từ điển điện tử có nút phát âm, gõ lần lượt zoo, tiger, monkey, bear và bấm loa cho HS nghe kèm hình minh hoạ; HS nhắc lại rồi chỉ vào đúng tranh trong SGK ứng với từ vừa nghe, từ nào cả lớp còn đọc lệch thì GV bấm nghe lại cho tới khi khớp mẫu.\n⚠ (Miền 4: An toàn) GV là người mở, dừng và tắt thiết bị; HS chỉ nghe rồi nhắc lại, không tự chạm vào máy tính và loa của lớp. Loa để vừa đủ nghe, dùng tai nghe thì mở nhỏ và bỏ ra ngay khi thấy ù tai; nghe liên tục khoảng 10-15 phút thì nghỉ. Từ điển điện tử chỉ mở đúng trang GV đã chuẩn bị trước giờ học, không bấm vào quảng cáo hiện ra bên cạnh.","hs":"- HS nghe giọng người bản ngữ đọc zoo, tiger, monkey, bear, nhắc lại đúng và chỉ được vào tranh trong SGK ứng với từ vừa nghe.\n- HS nghe lại phần audio GV cho lặp để tự sửa những từ mình đọc chưa giống mẫu trong Unit 20 “At the zoo”."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":33,"tiet":2,"bai":"Unit 20 — At the zoo — Lesson 1 (Zoo animals) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết zoo, tiger, monkey, bear; nghe hiểu mẫu câu \"Look at the tiger! It's big.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"Look at the tiger! It's big.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: zoo, tiger, monkey, bear; mẫu câu: Look at the tiger! It's big.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Zoo animals” (Unit 20 “At the zoo”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 20 “At the zoo”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"Look at the tiger! It's big.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":33,"tiet":3,"bai":"Unit 20 — At the zoo — Lesson 2 (Describing animals) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết elephant, giraffe, big, tall; nghe hiểu mẫu câu \"What are the monkeys doing? – They're jumping.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What are the monkeys doing? – They're jumping.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: elephant, giraffe, big, tall; mẫu câu: What are the monkeys doing? – They're jumping.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe và nhắc lại đúng mẫu câu “What are the monkeys doing? – They're jumping”, nghe ra được chỗ lên giọng và xuống giọng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 20 “At the zoo” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Describing animals”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 20 “At the zoo”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Presentation (Giới thiệu ngữ liệu)","gv":"- GV dùng tranh/flashcard giới thiệu từ mới: elephant, giraffe, big, tall.\n- Đọc mẫu, cho HS nghe audio và nhắc lại (Look, listen and repeat).\n- Giới thiệu mẫu câu: \"What are the monkeys doing? – They're jumping.\".","hs":"- HS quan sát tranh, nghe và nhắc lại từ/câu (đồng thanh – cá nhân).\n- Nhận diện nghĩa từ mới qua tranh."},{"ten":"3. Practice (Luyện tập có kiểm soát)","gv":"- GV cho HS luyện nói theo cặp (Point and say), thay thế từ trong mẫu câu.\n- Quan sát, sửa phát âm.","hs":"- HS luyện hỏi–đáp theo cặp dùng mẫu câu \"What are the monkeys doing? – They're jumping.\".\n- Đổi vai, sửa lỗi cho nhau."},{"ten":"4. Production (Vận dụng)","gv":"- GV cho HS thực hành mẫu câu trong tình huống thật (hỏi–đáp với bạn khác).","hs":"- HS vận dụng mẫu câu giao tiếp với bạn; xung phong trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Look, listen and repeat của Unit 20 “At the zoo” — Lesson 2 (Describing animals) cho HS nghe mẫu câu “What are the monkeys doing? – They're jumping” do người bản ngữ đọc; GV cho nghe lại đúng câu đó 2-3 lần và dừng ở chỗ lên giọng – xuống giọng để HS nghe ra ngữ điệu của câu hỏi khác câu trả lời thế nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV gõ elephant, giraffe, big, tall vào từ điển điện tử có phát âm và bấm loa cho cả lớp nghe từng từ; những từ HS đọc chưa đúng thì nghe lại rồi đọc theo cho tới khi khớp với mẫu, GV ghi các từ đó lên bảng để cuối tiết đọc lại một lượt.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và thao tác trên máy; HS ngồi tại chỗ nghe và nhắc lại. GV mở sẵn trang từ điển trước giờ học để không phải tìm kiếm trên mạng trước mặt HS; không bấm vào đường dẫn quảng cáo, không tải phần mềm lạ về máy của lớp. Âm lượng loa vừa đủ nghe, không mở to gây chói tai cho các bạn ngồi bàn đầu.","hs":"- HS nghe và nhắc lại đúng mẫu câu “What are the monkeys doing? – They're jumping”, nghe ra được chỗ lên giọng và xuống giọng.\n- HS nói được từ nào trong elephant, giraffe, big, tall mình đọc chưa giống mẫu và đọc lại theo phần audio GV mở lặp."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":33,"tiet":4,"bai":"Unit 20 — At the zoo — Lesson 2 (Describing animals) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận biết elephant, giraffe, big, tall; nghe hiểu mẫu câu \"What are the monkeys doing? – They're jumping.\".\n- Nói: hỏi–đáp và sử dụng đúng mẫu câu \"What are the monkeys doing? – They're jumping.\" trong tình huống giao tiếp đơn giản.\n- Đọc: đọc và nhận diện từ/câu chứa ngữ liệu mới.\n- Viết: chép/viết lại từ, cụm từ, câu ngắn theo mẫu.\nNgữ liệu trọng tâm: elephant, giraffe, big, tall; mẫu câu: What are the monkeys doing? – They're jumping.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Describing animals” (Unit 20 “At the zoo”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 20 “At the zoo”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Presentation (Mở rộng ngữ liệu)","gv":"- GV mở rộng: cho HS nghe và nhắc lại (Listen and repeat) phần chant/bài nghe; luyện trọng âm, ngữ điệu câu \"What are the monkeys doing? – They're jumping.\".","hs":"- HS nghe, nhắc lại theo audio; chú ý ngữ điệu, trọng âm."},{"ten":"3. Practice (Luyện tập)","gv":"- GV cho HS làm bài Listen and tick/Look and write; luyện nói theo nhóm.","hs":"- HS làm bài nghe/viết; luyện nói theo nhóm, trình bày."},{"ten":"4. Production (Vận dụng)","gv":"- GV tổ chức trò chơi/hoạt động giao tiếp để HS dùng mẫu câu một cách tự nhiên.","hs":"- HS chơi trò chơi giao tiếp; sử dụng mẫu câu linh hoạt."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":34,"tiet":1,"bai":"Unit 20 — At the zoo — Lesson 3 (Skills: Listen–Read–Write) – Tiết 1","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"At the zoo\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 20; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1a: Xác định được nhu cầu thông tin, tìm kiếm dữ liệu, thông tin và nội dung thông qua tìm kiếm đơn giản trong môi trường số: HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV chào lớp bằng tiếng Anh (Hello! How are you?). Tổ chức trò chơi khởi động gắn Unit 20 “At the zoo” (ví dụ “Slap the board”/“What's missing?” với tranh–từ liên quan).\n- Dẫn vào bài: giới thiệu “Skills: Listen–Read–Write”, gợi mở từ vựng/mẫu câu mới của tiết.","hs":"- HS chào lại bằng tiếng Anh, tham gia trò chơi theo Unit 20 “At the zoo”.\n- Nêu những từ/ý đã biết liên quan; sẵn sàng vào bài mới."},{"ten":"2. Listening (Nghe)","gv":"- GV mở audio bài nghe (Listen and tick/number). Hướng dẫn HS nghe 2–3 lần, chọn đáp án đúng.\n- Chữa bài, cho HS nghe lại và nhắc lại.","hs":"- HS nghe, làm bài tập nghe (tick/number/write).\n- Nghe lại, kiểm tra đáp án, nhắc lại câu."},{"ten":"3. Reading (Đọc)","gv":"- GV hướng dẫn HS đọc đoạn hội thoại/đoạn văn ngắn; tìm thông tin trả lời câu hỏi.","hs":"- HS đọc thầm, đọc thành tiếng theo cặp; trả lời câu hỏi đọc hiểu."},{"ten":"4. Practice (Luyện tập)","gv":"- GV cho HS luyện đọc theo cặp, đóng vai nhân vật trong bài.","hs":"- HS luyện đọc, đóng vai; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở phần Listen and repeat của Unit 20 “At the zoo” cho HS nghe âm và trọng âm trong từng từ; sau đó mở bài Listen and tick: lần 1 nghe trọn bài, lần 2 dừng sau mỗi câu để HS đánh dấu, lần 3 nghe lại để tự soát. Cách dừng và tua lại đúng chỗ này chỉ làm được với bản ghi âm.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu đáp án bài nghe, HS đối chiếu và tự đếm số câu đúng của mình; câu nào sai thì GV tua đúng đoạn audio ấy cho nghe lại và cả lớp cùng chỉ ra từ khoá đã nghe sót trong bài đọc về At the zoo.\n⚠ (Miền 4: An toàn) Bài nghe do GV mở từ tệp đã chuẩn bị sẵn; nếu lấy trên mạng thì GV mở và tắt quảng cáo trước giờ học, không tìm kiếm trước mặt HS. HS không dùng điện thoại để ghi âm giọng bạn trong giờ nghe. Nghe qua loa, âm lượng vừa phải, mỗi lượt nghe không kéo dài quá 15 phút rồi cho mắt và tai nghỉ.","hs":"- HS nghe được bài Listen and tick của Unit 20 “At the zoo”, đánh dấu đúng thông tin và tự đếm số câu mình làm đúng.\n- HS chỉ ra được từ khoá mình nghe sót khi được nghe lại đúng đoạn audio đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":34,"tiet":2,"bai":"Unit 20 — At the zoo — Lesson 3 (Skills: Listen–Read–Write) – Tiết 2","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Nghe: nghe và nhận diện thông tin trong đoạn hội thoại/bài đọc ngắn về chủ đề \"At the zoo\".\n- Đọc: đọc hiểu câu/đoạn ngắn, tìm thông tin cụ thể.\n- Viết: viết được câu ngắn theo mẫu về chủ đề bài học.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\nNgữ liệu trọng tâm: ôn từ Unit 20; mẫu câu: tổng hợp nghe–nói–đọc–viết\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động luyện tập phát âm, ghi nhớ từ mới.\n- Giao tiếp và hợp tác: mạnh dạn hỏi–đáp theo cặp/nhóm bằng tiếng Anh.\n- Giải quyết vấn đề và sáng tạo: vận dụng mẫu câu vào tình huống mới.\n3. Phẩm chất:\n- Chăm chỉ: tích cực luyện nghe–nói, hoàn thành nhiệm vụ.\n- Nhân ái, tôn trọng: lịch sự khi chào hỏi, hợp tác với bạn.\n- Trách nhiệm: giữ gìn đồ dùng học tập, dùng thiết bị số an toàn.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chant hoặc hát được bài của Unit 20 “At the zoo” đúng nhịp theo nhạc và lời chạy trên màn hình.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS nhắc lại từ vựng/mẫu câu đã học ở tiết trước của “Skills: Listen–Read–Write” (Unit 20 “At the zoo”) qua hỏi–đáp nhanh hoặc flashcard.\n- Kết nối vào phần luyện tập – vận dụng của bài.","hs":"- HS nhắc lại từ/mẫu câu đã học, hỏi–đáp theo cặp về Unit 20 “At the zoo”.\n- Sẵn sàng luyện tập, vận dụng."},{"ten":"2. Writing (Viết)","gv":"- GV hướng dẫn HS viết câu theo mẫu (điền từ, hoàn thành câu, viết về bản thân/bạn bè theo chủ đề).\n- Sửa lỗi chính tả, ngữ pháp cơ bản.","hs":"- HS viết câu/đoạn ngắn theo mẫu; đọc lại bài viết.\n- Chữa lỗi theo hướng dẫn của GV."},{"ten":"3. Production – Project (Vận dụng)","gv":"- GV tổ chức hoạt động vận dụng: giới thiệu bản thân/bạn/đồ vật... theo chủ đề Unit 20 trước lớp.","hs":"- HS trình bày ngắn bằng tiếng Anh; các bạn nghe, nhận xét, cổ vũ."},{"ten":"4. Consolidation (Củng cố)","gv":"- GV chốt từ vựng, mẫu câu trọng tâm; nhận xét, dặn dò tự luyện ở nhà.","hs":"- HS nhắc lại nội dung chính; ghi nhớ bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bài chant/bài hát của Unit 20 “At the zoo” trên máy chiếu kèm lời chạy trên màn hình: cho nghe lần 1 để nắm nhịp, lần 2 chant nối theo từng câu, sau đó bật riêng phần nhạc nền không lời để cả lớp tự chant — nhìn lời chạy đúng nhịp giúp HS bắt được chỗ ngắt câu mà nhìn chữ trong sách không thấy.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) Ở phần Project, HS làm sản phẩm giấy về At the zoo (tranh vẽ, tấm thẻ từ, bảng thông tin); GV dùng điện thoại chụp lại sản phẩm của từng em rồi chiếu lên màn hình để cả lớp cùng nhìn rõ và nhận xét, em nào cũng được giới thiệu bài của mình.\n⚠ (Miền 4: An toàn) GV là người cầm máy chụp và chiếu sản phẩm; ảnh chỉ chiếu trong lớp rồi xoá, không đăng lên mạng xã hội hay nhóm chat của phụ huynh. Trên sản phẩm và trong ảnh không để họ tên đầy đủ, địa chỉ nhà, số điện thoại của HS. Bạn nào chưa muốn bài mình được chiếu thì GV tôn trọng, không ép.","hs":"- HS chant hoặc hát được bài của Unit 20 “At the zoo” đúng nhịp theo nhạc và lời chạy trên màn hình.\n- HS giới thiệu được sản phẩm của mình về At the zoo khi ảnh được chiếu lên màn hình và nghe bạn nhận xét."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":34,"tiet":3,"bai":"Review 4 (Ôn tập – Nghe – Đọc)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 16–20.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.\n4. Tích hợp\n- Năng lực số 5.4 CB1a: Nhận ra được năng lực số của tôi cần được cải thiện hoặc cập nhật ở đâu: HS làm được bài ôn tương tác của “Review 4 (Ôn tập – Nghe – Đọc)” và tự biết mình còn yếu ở phần nào của Unit 16–20.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 16–20.\n- Nêu mục tiêu Review 4: củng cố kĩ năng Nghe và Đọc.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 16–20.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ bài tập tương tác có chấm tự động cho “Review 4 (Ôn tập – Nghe – Đọc)” với ngữ liệu Unit 16–20: nghe rồi chọn tranh, nối từ với hình, chọn câu trả lời đúng. Làm xong câu nào HS biết ngay đúng hay sai, tự đếm được mình còn yếu ở phần nghe hay phần đọc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở lại đúng đoạn audio của Unit 16–20 mà cả lớp làm sai nhiều nhất, cho nghe chậm từng câu; HS chỉ ra từ khoá mình đã nghe sót rồi làm lại câu đó.\n⚠ (Miền 4: An toàn) HS làm hết bài rồi mới xem đáp án, xem để hiểu chứ không phải để chép; máy chấm đúng sai chứ không chấm em giỏi hay kém, làm sai thì làm lại. Nếu làm bài trên máy tính bảng của lớp thì dùng đúng máy được phát, không mở sang trang khác; phần mềm hỏi tên thì chỉ gõ tên gọi ở nhà hoặc số thứ tự trong lớp, không gõ họ tên đầy đủ.","hs":"- HS làm được bài ôn tương tác của “Review 4 (Ôn tập – Nghe – Đọc)” và tự biết mình còn yếu ở phần nào của Unit 16–20.\n- HS nghe lại đoạn audio mình làm sai, chỉ ra từ khoá đã nghe sót và làm lại câu đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":34,"tiet":4,"bai":"Review 4 (Ôn tập – Nói – Viết)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 16–20.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 16–20.\n- Nêu mục tiêu Review 4: củng cố kĩ năng Nói và Viết.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 16–20.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":35,"tiet":1,"bai":"Review 4 (Ôn tập – Fun time & Củng cố)","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- Ôn tập, củng cố từ vựng và mẫu câu của các Unit 16–20.\n- Nghe: nghe hiểu và làm bài tập nghe tổng hợp.\n- Nói: hỏi–đáp lại các mẫu câu đã học.\n- Đọc: đọc hiểu đoạn ngắn.\n- Viết: viết câu theo mẫu.\n2. Năng lực chung:\n- Tự chủ và tự học; Giao tiếp và hợp tác; Giải quyết vấn đề.\n3. Phẩm chất:\n- Chăm chỉ ôn luyện; tự tin giao tiếp; trách nhiệm với việc học.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS tham gia trò chơi ôn ngữ liệu Unit 16–20 trong “Review 4 (Ôn tập – Fun time & Củng cố)” và biết ngay mình còn nhớ được những từ nào.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV tổ chức trò chơi ôn tập nhanh (“Lucky number”/“Brainstorming”) hệ thống từ vựng – mẫu câu đã học từ Unit 16–20.\n- Nêu mục tiêu Review 4: củng cố trò chơi ngôn ngữ, hệ thống hoá từ vựng – mẫu câu.","hs":"- HS tham gia trò chơi, nhắc lại chủ đề – từ vựng Unit 16–20.\n- Nắm mục tiêu tiết ôn tập."},{"ten":"2. Ôn luyện kỹ năng","gv":"- GV cho HS làm lần lượt các bài Listen / Read / Write trong phần Review; chữa bài, giải thích.","hs":"- HS làm bài ôn tập; chữa bài, tự đánh giá."},{"ten":"3. Fun time / Trò chơi ngôn ngữ","gv":"- GV tổ chức trò chơi, bài hát, đố vui bằng tiếng Anh để củng cố nhẹ nhàng.","hs":"- HS tham gia vui vẻ, sử dụng tiếng Anh trong trò chơi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV tổ chức phần Fun time của “Review 4 (Ôn tập – Fun time & Củng cố)” bằng trò chơi ôn từ trên máy chiếu (lật thẻ tìm cặp từ – tranh, ô chữ, vòng quay chọn từ) với ngữ liệu Unit 16–20; các tổ thi tìm nhanh, máy giữ điểm và báo đúng sai ngay nên cả lớp nhìn thấy mình còn nhớ được bao nhiêu từ.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV thao tác cho cả lớp nghe một câu ôn tập của Unit 16–20 đọc bằng hai giọng: giọng người bản ngữ trong audio SGK và giọng do máy tự đọc; HS chỉ ra chỗ máy đọc đều đều, nối âm chưa tự nhiên, từ đó hiểu vì sao luyện phát âm vẫn phải nghe audio của SGK. HS chỉ nghe và nhận xét, không tự dùng công cụ này.\n⚠ (Miền 4: An toàn) GV là người mở trò chơi và mở công cụ đọc mẫu; HS ngồi tại chỗ, không tự vào máy của lớp. Chơi theo tổ thì thắng thua đều vui vẻ, không chê bạn đọc sai — trò chơi để ôn bài chứ không để so bì. Không nhập tên thật của HS vào phần mềm trò chơi trên mạng, chỉ dùng tên tổ hoặc số thứ tự.","hs":"- HS tham gia trò chơi ôn ngữ liệu Unit 16–20 trong “Review 4 (Ôn tập – Fun time & Củng cố)” và biết ngay mình còn nhớ được những từ nào.\n- HS chỉ ra được chỗ giọng máy đọc chưa tự nhiên so với giọng người bản ngữ trong audio SGK."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":35,"tiet":2,"bai":"Ôn tập cuối học kì II","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- ôn tập tổng hợp từ vựng, mẫu câu Unit 11–20; luyện các kỹ năng nghe–nói–đọc–viết.\n2. Năng lực chung: Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất: Chăm chỉ, tự tin, trung thực trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 5.4 CB1a: Nhận ra được năng lực số của tôi cần được cải thiện hoặc cập nhật ở đâu: HS làm được bài ôn tương tác của “Ôn tập cuối học kì II” và tự biết mình còn yếu ở phần nào của Unit 11–20.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV cho HS chơi trò chơi/hỏi–đáp nhanh để huy động lại kiến thức đã học trong học kì.\n- Nêu mục tiêu tiết ôn tập, hệ thống các Unit trọng tâm chuẩn bị kiểm tra.","hs":"- HS tham gia, nhắc lại chủ đề – từ vựng; xác định nội dung cần ôn."},{"ten":"2. Nội dung chính","gv":"- GV tổ chức ôn tập tổng hợp từ vựng, mẫu câu Unit 11–20; luyện các kỹ năng nghe–nói–đọc–viết.","hs":"- HS thực hiện nhiệm vụ theo hướng dẫn."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập/làm bài, chữa và nhận xét.","hs":"- HS làm bài, tự đánh giá, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ bài tập tương tác có chấm tự động cho “Ôn tập cuối học kì II” với ngữ liệu Unit 11–20: nghe rồi chọn tranh, nối từ với hình, chọn câu trả lời đúng. Làm xong câu nào HS biết ngay đúng hay sai, tự đếm được mình còn yếu ở phần nghe hay phần đọc.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở lại đúng đoạn audio của Unit 11–20 mà cả lớp làm sai nhiều nhất, cho nghe chậm từng câu; HS chỉ ra từ khoá mình đã nghe sót rồi làm lại câu đó.\n⚠ (Miền 4: An toàn) HS làm hết bài rồi mới xem đáp án, xem để hiểu chứ không phải để chép; máy chấm đúng sai chứ không chấm em giỏi hay kém, làm sai thì làm lại. Nếu làm bài trên máy tính bảng của lớp thì dùng đúng máy được phát, không mở sang trang khác; phần mềm hỏi tên thì chỉ gõ tên gọi ở nhà hoặc số thứ tự trong lớp, không gõ họ tên đầy đủ.","hs":"- HS làm được bài ôn tương tác của “Ôn tập cuối học kì II” và tự biết mình còn yếu ở phần nào của Unit 11–20.\n- HS nghe lại đoạn audio mình làm sai, chỉ ra từ khoá đã nghe sót và làm lại câu đó."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":35,"tiet":3,"bai":"Kiểm tra định kì cuối học kì II","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- kiểm tra đánh giá định kì cuối năm (nghe, đọc, viết, nói) theo Thông tư 27/2020/TT-BGDĐT.\n2. Năng lực chung: Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất: Chăm chỉ, tự tin, trung thực trong kiểm tra – đánh giá.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV ổn định lớp, tạo tâm lí thoải mái, tự tin trước khi làm bài.\n- Nhắc hình thức, thời gian và quy tắc làm bài kiểm tra; phát đề.","hs":"- HS chuẩn bị đồ dùng, giữ trật tự, lắng nghe hướng dẫn làm bài."},{"ten":"2. Nội dung chính","gv":"- GV tổ chức kiểm tra đánh giá định kì cuối năm (nghe, đọc, viết, nói) theo Thông tư 27/2020/TT-BGDĐT.","hs":"- HS thực hiện nhiệm vụ theo hướng dẫn."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập/làm bài, chữa và nhận xét.","hs":"- HS làm bài, tự đánh giá, rút kinh nghiệm."}]},
{"lop":3,"mon":"Tiếng Anh","tuan":35,"tiet":4,"bai":"Chữa bài & tổng kết năm học","yccd":"1. Năng lực ngôn ngữ (đặc thù):\n- chữa bài kiểm tra, tổng kết – động viên; định hướng tự học tiếng Anh dịp hè.\n2. Năng lực chung: Tự chủ và tự học; Giao tiếp và hợp tác.\n3. Phẩm chất: Chăm chỉ, tự tin, trung thực trong kiểm tra – đánh giá.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe lại phát âm chuẩn của những từ mình làm sai trong “Chữa bài & tổng kết năm học” và chép được vào sổ tay từ vựng.","dodung":"- GV: Loa/đài, máy tính, máy chiếu, file nghe (audio) SGK Tiếng Anh 3 (Global Success), tranh/flashcard theo chủ đề, bài giảng điện tử.\n- HS: SGK Tiếng Anh 3 (Global Success), vở, bút chì, đồ dùng học tập.","hoatdong":[{"ten":"1. Warm-up (Khởi động)","gv":"- GV nhận xét chung kết quả kiểm tra, động viên tinh thần học tập.\n- Dẫn vào tiết chữa bài – củng cố những nội dung HS còn sai sót.","hs":"- HS lắng nghe, đối chiếu bài làm, ghi nhận phần cần sửa."},{"ten":"2. Nội dung chính","gv":"- GV tổ chức chữa bài kiểm tra, tổng kết – động viên; định hướng tự học tiếng Anh dịp hè.","hs":"- HS thực hiện nhiệm vụ theo hướng dẫn."},{"ten":"3. Luyện tập – Vận dụng","gv":"- GV cho HS luyện tập/làm bài, chữa và nhận xét.","hs":"- HS làm bài, tự đánh giá, rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) Sau khi trả bài trong tiết “Chữa bài & tổng kết năm học”, GV mở lại đúng những đoạn audio và những từ cả lớp sai nhiều nhất; GV gõ từng từ vào từ điển điện tử có nút phát âm, bấm loa cho HS nghe lại 2-3 lần rồi HS chép từ đó vào sổ tay từ vựng viết tay của mình.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV thao tác cho HS xem: gõ một câu tiếng Việt trong bài vào công cụ dịch tự động, máy trả về một câu tiếng Anh chưa đúng với mẫu câu các em đã học; GV cùng cả lớp sửa lại theo đúng mẫu câu trong SGK. HS thấy được máy dịch chỉ để tham khảo, chưa thay được việc mình học thuộc mẫu câu.\n⚠ (Miền 4: An toàn) Chỉ GV gõ và mở công cụ dịch trên máy của lớp; HS lớp 3 chưa tự dùng công cụ dịch để làm bài. Không chụp bài kiểm tra của mình hay của bạn gửi ra ngoài lớp; điểm số và bài làm của mỗi bạn là chuyện riêng, không đem ra chê cười. Sổ tay từ vựng HS tự chép tay để nhớ mặt chữ.","hs":"- HS nghe lại phát âm chuẩn của những từ mình làm sai trong “Chữa bài & tổng kết năm học” và chép được vào sổ tay từ vựng.\n- HS nêu được vì sao câu do máy dịch chưa dùng được ngay mà phải sửa lại theo mẫu câu đã học."}]}
];
